module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
    output wire o_mon
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
    reg [3:0] out_r;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
    initial mon     = 1'b0;
    initial pv      = 1'b0;

    wire acc_iss = i_ce && i_issue  && (out_r <  WINDOW);
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
            empty_q <= (iss == ret);
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
