module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
    wire mism0 = v0 && (p0 != (^d0));
    wire mism1 = v1 && (p1 != (^d1));
    wire retry = mism0 || mism1;

    always @(posedge clk) begin
        if (i_ce) begin
            o_retry <= retry;
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
            end else begin
