            if (i_clear) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
                total <= 8'h00;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
                total <= total + i_data;
            end
        end
