module dma_burst_engine (
    input  wire       clk,
    input  wire       ce,      // global enable: low => all state frozen
    input  wire       start,
    input  wire [4:0] len_in,
    input  wire       resp,    // a beat response returns
    output reg        busy
);
    // beats still to be issued in the current burst
    reg [4:0] beats_rem = 5'd0;
    // outstanding (issued, not yet responded) beats
    reg [3:0] outst     = 4'd0;
    // free issue slots; by construction outst + credits == 4
    reg [3:0] credits   = 4'd4;

    initial busy = 1'b0;

    // burst length is clamped to the engine maximum of 12 beats
    wire [4:0] len_cap = (len_in > 5'd12) ? 5'd12 : len_in;

    wire do_load  = ce && !busy && start && (len_cap != 5'd0);
    wire do_issue = ce &&  busy && (credits != 4'd0);
    wire do_resp  = ce &&  resp && (outst   != 4'd0);

    // beats-remaining counter and busy flag
    always @(posedge clk) begin
        if (do_load) begin
            beats_rem <= len_cap;
            busy      <= 1'b1;
        end else if (do_issue) begin
            beats_rem <= beats_rem - 5'd1;
            if (beats_rem == 5'd1)
                busy <= 1'b0;
        end
    end

    // outstanding / credit bookkeeping
    always @(posedge clk) begin
        if (do_issue && !do_resp) begin
            outst   <= outst   + 4'd1;
            credits <= credits - 4'd1;
        end else if (do_resp && !do_issue) begin
            outst   <= outst   - 4'd1;
            credits <= credits + 4'd1;
        end
    end

    // P: while the engine is busy, at most 4 beats are ever outstanding
    always @(posedge clk)
        if (busy)
            assert (outst <= 4'd4);
