                2'b10:   tokens <= tokens + 3'd1;
                2'b01:   tokens <= tokens - 3'd1;
                default: tokens <= tokens;
            endcase

            // arm -> start -> finish chain
            case (state)
                S_IDLE: begin
                    if (req) begin
                        state        <= S_ARM;
                        armed_seen   <= 1'b1;
                        started_seen <= 1'b0;
                    end
                end
                S_ARM: begin
                    if (cancel) begin
                        state      <= S_IDLE;
                        armed_seen <= 1'b0;
                    end else if (can_start) begin
                        state        <= S_RUN;
                        started_seen <= 1'b1;
                    end
                end
                S_RUN: begin
                    if (done) begin
                        state        <= S_IDLE;
                        armed_seen   <= 1'b0;
                        started_seen <= 1'b0;
                    end
                end
                default: begin
                    state        <= S_IDLE;
                    armed_seen   <= 1'b0;
                    started_seen <= 1'b0;
                end
            endcase
        end
    end

    // chain precedence: a finish can never be observed unless this
    // transaction was armed and then started
    always @(*)
        if (o_finish)
            assert (armed_seen && started_seen);
