// Sliding-window grant rate limiter for an inference-accelerator arbiter.
// A shift register of the last 8 cycles' grants plus a mirrored count of ones.
module window_rate_limiter (
    input  wire clk,
    input  wire ce,      // idle condition: when low, nothing changes
    input  wire req,     // request a grant this cycle
    input  wire flush,   // clear the accounting (credit reset)
    output wire grant,
    output wire full
);
    localparam [3:0] LIMIT = 4'd4;

    // sliding window of recent grants and its mirrored population count
    reg [7:0] win        = 8'd0;
    reg [3:0] ones       = 4'd0;

    // shadow register: saturating count of grants ever issued (since last flush)
    reg [2:0] seen       = 3'd0;

    // scope arming register: high until the first flush ever happens
    reg       pre_flush  = 1'b1;

    // registered throttle indication
    reg       throttled  = 1'b0;

    reg       pv         = 1'b0;

    assign full  = (ones >= LIMIT);
    assign grant = ce && !flush && req && !full;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (flush) begin
                seen      <= 3'd0;
                pre_flush <= 1'b0;
                throttled <= 1'b0;
            end else begin
                win  <= {win[6:0], grant};
                ones <= ones + (grant ? 4'd1 : 4'd0) - (win[7] ? 4'd1 : 4'd0);
                if (grant && (seen != 3'd4))
                    seen <= seen + 3'd1;
                throttled <= req && full;
            end
        end
    end

    // Precedence, before-first-flush scope, edge style:
    // the throttle signal may only rise after LIMIT grants have been observed.
    always @(posedge clk)
        if (pv && pre_flush && $rose(throttled))
            assert (seen == 3'd4);
endmodule

