module crc8_onehot_check (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire data_bit,
    output reg [3:0] st,
    output reg [7:0] crc,
    output reg [2:0] bitcnt,
    output reg crc_busy,
    output reg crc_valid
);
    // one-hot phases: bit0 = IDLE, bit1 = SHIFT, bit2 = FINAL, bit3 = DONE
    initial st        = 4'b0001;
    initial crc       = 8'hFF;
    initial bitcnt    = 3'd0;
    initial crc_busy  = 1'b0;
    initial crc_valid = 1'b0;

    wire       fb       = crc[7] ^ data_bit;
    wire [7:0] crc_next = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);

    always @(posedge clk) begin
        if (rst) begin
            st        <= 4'b0001;
            crc       <= 8'hFF;
            bitcnt    <= 3'd0;
            crc_busy  <= 1'b0;
            crc_valid <= 1'b0;
        end else if (ce) begin
            // IDLE arm: accepting a new byte starts the shifter
            if (st[0]) begin
                if (start) begin
                    st       <= 4'b0010;
                    crc      <= 8'hFF;
                    bitcnt   <= 3'd0;
                    crc_busy <= 1'b1;
                end
            end
            // SHIFT arm: one bit of the polynomial reduction per cycle
            if (st[1]) begin
                crc    <= crc_next;
                bitcnt <= bitcnt + 3'd1;
                if (bitcnt == 3'd7) begin
                    st       <= 4'b0100;
                    crc_busy <= 1'b0;
                end
            end
            // FINAL arm: remainder settled, publish it
            if (st[2]) begin
                st        <= 4'b1000;
                crc_valid <= 1'b1;
            end
            // DONE arm: consumer has seen the result
            if (st[3]) begin
                st        <= 4'b0001;
                crc_valid <= 1'b0;
            end
        end
    end

    always @(*)
        assert (!(crc_busy && crc_valid));
endmodule

