module prio_arb_lock (
    input  wire       clk,
    input  wire       ce,
    input  wire [3:0] req,
    output reg  [3:0] grant
);
    // fixed-priority arbiter (master 0 highest) with a lock bit that freezes
    // the current winner until that winner drops its request
    reg       locked;
    reg [1:0] lock_id;
    reg       armed;   // sticky: set the first time a grant is ever issued
    reg       pv;      // past-valid

    initial begin
        grant   = 4'b0000;
        locked  = 1'b0;
        lock_id = 2'd0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire       any = |req;
    wire [1:0] win = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            if (locked) begin
                if (req[lock_id]) begin
                    // hold the locked winner: grant is re-driven from lock_id
                    grant   <= (4'b0001 << lock_id);
                    locked  <= 1'b1;
                    armed   <= 1'b1;
                end else begin
                    // winner released: drop the lock for one cycle
                    grant   <= 4'b0000;
                    locked  <= 1'b0;
                end
            end else begin
                if (any) begin
                    grant   <= (4'b0001 << win);
                    lock_id <= win;
                    locked  <= 1'b1;
                    armed   <= 1'b1;
                end else begin
                    grant   <= 4'b0000;
                    locked  <= 1'b0;
                end
            end
        end
    end

    // Universality, after the arbiter has ever granted (armed):
    // while the lock bit did not change and is held, the grant must not change.
    always @(posedge clk)
        if (pv && armed && locked && $stable(locked))
            assert ($stable(grant));
endmodule

