module json_watchdog (
    input  wire clk,
    input  wire i_ce,      // parser step enable; low = idle, no state changes
    input  wire kick,      // parser signals progress on the document stream
    output reg  expired,   // watchdog fired: no kick within LIMIT steps
    output reg  halted     // parse session shut down after the strike cap
