    localparam [3:0] LIMIT = 4'd6;

    // stall counter: steps since the last kick
    reg [3:0] timer;
    // registered "timer is one tick short of LIMIT" marker
    reg       pre;
    // how many times the watchdog has fired during this session
    reg [2:0] strikes;

    reg pv; // past-valid

    initial begin
        timer   = 4'd0;
        pre     = 1'b0;
        expired = 1'b0;
        halted  = 1'b0;
        strikes = 3'd0;
        pv      = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce && !halted) begin
            if (kick) begin
                // parser made progress: rearm the watchdog
                timer   <= 4'd0;
                pre     <= 1'b0;
                expired <= 1'b0;
            end else if (!expired) begin
