module cart_write_elastic (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_req,
    input  wire       i_two,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_valid,
    output wire       o_busy
);
    // two-entry elastic buffer for flash program bytes
    reg       v_head, v_tail;   // head/tail occupancy flags
    reg [7:0] d_head, d_tail;
    reg [1:0] count;            // occupancy counter, mirrors the flags
    reg [2:0] timer;            // completion countdown
    reg       win;              // window register: armed on accept, cleared on drain

    initial v_head = 1'b0;
    initial v_tail = 1'b0;
    initial d_head = 8'h00;
    initial d_tail = 8'h00;
    initial count  = 2'd0;
    initial timer  = 3'd0;
    initial win    = 1'b0;

    always @(posedge clk) begin
        if (i_rst) begin
            v_head <= 1'b0;
            v_tail <= 1'b0;
            d_head <= 8'h00;
            d_tail <= 8'h00;
            count  <= 2'd0;
            timer  <= 3'd0;
            win    <= 1'b0;
        end else if (i_ce) begin
            if (!win) begin
                // accept a new burst request (one or two bytes)
                if (i_req) begin
                    v_head <= 1'b1;
                    d_head <= i_data;
                    v_tail <= i_two;
                    d_tail <= i_data ^ 8'h5a;
                    count  <= i_two ? 2'd2 : 2'd1;
                    timer  <= 3'd3;
                    win    <= 1'b1;
                end
            end else begin
                // draining: one byte committed to the cart per enabled cycle
                timer <= timer - 3'd1;
                if (count == 2'd2) begin
                    d_head <= d_tail;
                    v_tail <= 1'b0;
                    count  <= 2'd1;
                end else begin
                    v_head <= 1'b0;
                    count  <= 2'd0;
                    win    <= 1'b0;
                end
            end
        end
    end

    assign o_data  = d_head;
    assign o_valid = v_head;
    assign o_busy  = win;

    // Bounded response (safety): the countdown never expires while the
    // accepted burst is still outstanding.
    always @(posedge clk)
        if (win)
            assert (timer != 3'd0);
