module txn_scoreboard_deadline (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_issue,
    input  wire       i_retire,
    output wire [3:0] o_outstanding,
    output wire       o_armed
);
    // Scoreboard: issued vs retired transaction counters.
    reg [3:0] issued   = 4'd0;
    reg [3:0] retired  = 4'd0;
    // Completion countdown for the oldest outstanding transaction.
    reg [2:0] deadline = 3'd5;
    // Registered early-warning flag that triggers the forced retire.
    reg       urgent   = 1'b0;
    // Sticky arm: set the first time a transaction is ever accepted.
    reg       armed    = 1'b0;

    wire [3:0] outstanding = issued - retired;

    wire issue_ok  = i_issue && (outstanding < 4'd4);
    wire force_ret = urgent && (deadline == 3'd1);
    wire retire_ok = (outstanding != 4'd0) && (i_retire || force_ret);

    wire [3:0] out_n = outstanding
                     + (issue_ok  ? 4'd1 : 4'd0)
                     - (retire_ok ? 4'd1 : 4'd0);

    wire [2:0] dl_n = (retire_ok || (issue_ok && (outstanding == 4'd0))) ? 3'd5 :
                      ((outstanding != 4'd0) ? (deadline - 3'd1) : deadline);

    always @(posedge clk) begin
        if (i_ce) begin
            if (issue_ok)  issued  <= issued  + 4'd1;
            if (retire_ok) retired <= retired + 4'd1;
            deadline <= dl_n;
            urgent   <= (out_n != 4'd0) && (dl_n <= 3'd2);
            if (issue_ok) armed <= 1'b1;
        end
    end

    assign o_outstanding = outstanding;
    assign o_armed       = armed;

    // Bounded response (safety form), after-Q scope: once the scoreboard has
    // ever accepted a transaction, the completion countdown must never expire
    // while work is still outstanding.
    always @(posedge clk)
        if (armed && (outstanding != 4'd0))
            assert (deadline != 3'd0);
endmodule

