    wire [3:0] base = {last[2:0], last[3]};

    // unrolled ring scan over two copies of the request vector
    wire [7:0] r8 = {req, req};
    wire [7:0] b8 = {base, base};
    wire [7:0] tok;

    assign tok[0] = b8[0];
    assign tok[1] = b8[1] | (tok[0] & ~r8[0]);
    assign tok[2] = b8[2] | (tok[1] & ~r8[1]);
    assign tok[3] = b8[3] | (tok[2] & ~r8[2]);
    assign tok[4] = b8[4] | (tok[3] & ~r8[3]);
    assign tok[5] = b8[5] | (tok[4] & ~r8[4]);
    assign tok[6] = b8[6] | (tok[5] & ~r8[5]);
    assign tok[7] = b8[7] | (tok[6] & ~r8[6]);

    wire [7:0] g8  = r8 & tok;
    wire [3:0] gnt = g8[3:0] | g8[7:4];

    initial last   = 4'b0001;
    initial grant  = 4'b0000;
    initial gvalid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            last   <= 4'b0001;
            grant  <= 4'b0000;
            gvalid <= 1'b0;
        end else if (ce) begin
            grant  <= gnt;
            gvalid <= |gnt;
            if (|gnt)
                last <= gnt;
        end
    end

    // P: whenever a grant is outstanding, no two lines are granted together
    always @(posedge clk)
        if (gvalid)
            assert ((grant & (grant - 4'd1)) == 4'd0);
