    // never through the pointer itself
    localparam [3:0] LIMIT = 4'd10;

    wire [3:0] sp_next = sp + 4'd1;

    assign full = (hwm >= LIMIT);

    initial sp  = 4'd0;
    initial hwm = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
        end else if (pop && (sp != 4'd0)) begin
            sp  <= sp - 4'd1;          // mark never falls back
        end else if (push && !full) begin
            sp  <= sp_next;
            if (sp_next > hwm)
                hwm <= sp_next;        // mark only ratchets upward
        end
    end

    // P, part 1: occupancy never exceeds 10 though 4 bits allow 15
    always @(posedge clk)
        assert (sp <= LIMIT);

    // P, part 2: the high-water mark never exceeds 10 either
    always @(posedge clk)
        assert (hwm <= LIMIT);
