    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [3:0]  i_len,
    input  wire [27:0] i_addr,
    output wire        o_busy,
    output wire        o_last,
    output wire [27:0] o_addr,
    output wire [3:0]  o_sent
