// Tracks UART frames in flight through a fixed-latency 4-stage serializer.
// Each issued frame is marked in a shift register; it retires 4 cycles later.
// occ is an independently maintained occupancy counter.
module uart_inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // baud tick / pipeline advance enable
    input  wire       i_issue,   // a new frame is handed to the serializer
    output wire       o_idle,    // tracker says: nothing outstanding
    output wire       o_inflight,// serializer stages say: something outstanding
    output wire       o_retire,  // a frame leaves the last stage this tick
    output wire [2:0] o_count
);

    reg [3:0] pipe;  // one mark per occupied serializer stage
    reg [2:0] occ;   // running occupancy count

    initial pipe = 4'b0000;
    initial occ  = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            pipe <= 4'b0000;
            occ  <= 3'd0;
        end else if (i_ce) begin
            pipe <= {pipe[2:0], i_issue};
            occ  <= occ + (i_issue ? 3'd1 : 3'd0) - (pipe[3] ? 3'd1 : 3'd0);
        end
    end

    assign o_idle     = (occ == 3'd0);
    assign o_inflight = |pipe;
    assign o_retire   = i_ce && pipe[3];
    assign o_count    = occ;

    // P: the tracker can never claim idle while a stage still holds a frame.
    always @(*)
        assert (!(o_idle && o_inflight));

endmodule

