    reg       at_max;   // "full"  status flag
    reg       at_min;   // "empty" status flag
    reg       pv;       // past-valid

    initial cnt    = 4'd0;
    initial at_max = 1'b0;
    initial at_min = 1'b1;
    initial pv     = 1'b0;

