module elastic_skid_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_valid,
    output wire       o_full
);
    // two-entry elastic buffer with head/tail flags and a redundant occupancy count
    reg [7:0] mem0;
    reg [7:0] mem1;
    reg       v0;
    reg       v1;
    reg       head;
    reg       tail;
    reg [2:0] count;

    initial begin
        mem0  = 8'd0;
        mem1  = 8'd0;
        v0    = 1'b0;
        v1    = 1'b0;
        head  = 1'b0;
        tail  = 1'b0;
        count = 3'd0;
    end

    wire full  = v0 && v1;
    wire empty = !v0 && !v1;

    wire do_push = i_push && !full;
    wire do_pop  = i_pop  && !empty;

    assign o_full  = full;
    assign o_valid = !empty;
    assign o_data  = head ? mem1 : mem0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            head  <= 1'b0;
            tail  <= 1'b0;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                if (tail) begin
                    mem1 <= i_data;
                    v1   <= 1'b1;
                end else begin
                    mem0 <= i_data;
                    v0   <= 1'b1;
                end
                tail <= ~tail;
            end

            if (do_pop) begin
                if (head)
                    v1 <= 1'b0;
                else
                    v0 <= 1'b0;
                head <= ~head;
            end

            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;
        end
    end

    // P: occupancy never exceeds the two-entry depth, although the counter is 3 bits wide
    always @(posedge clk)
        assert (count <= 3'd2);
endmodule

