module frame_fifo (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire       push,    // request: enqueue a frame command
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       full,
    output wire       empty,
    output wire       expired
);
    // ---- FIFO state: two pointers plus an occupancy counter -------------
    reg [2:0] wptr  = 3'd0;
    reg [2:0] rptr  = 3'd0;
    reg [2:0] count = 3'd0;   // occupancy, capacity 7 so diff is unambiguous

    // ---- bounded-response countdown for the drain engine ----------------
    reg [3:0] timer = 4'd0;

    // ---- sticky arm: set the first time a request is accepted -----------
    reg       armed = 1'b0;

    reg [7:0] mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'd0;
    end

    assign full    = (count == 3'd7);
    assign empty   = (count == 3'd0);
    assign dout    = mem[rptr];
    assign expired = (timer == 4'd0);

    // write port has priority; the drain engine pops on any idle-of-push cycle
    wire       wr = push && !full;
    wire       rd = !push && !empty;

    // next write pointer and the resulting pointer difference
    wire [2:0] nwptr = wptr + {2'b00, wr};
    wire [2:0] ndiff = nwptr - rptr;

    always @(posedge clk) begin
        if (ce) begin
            if (wr) begin
                mem[wptr] <= din;
                wptr      <= wptr + 3'd1;
                armed     <= 1'b1;
            end
            if (rd)
                rptr <= rptr + 3'd1;

            count <= count + {2'b00, wr} - {2'b00, rd};

            // a new request reloads the deadline from the pointer distance
            if (push)
                timer <= {1'b0, ndiff} + 4'd2;
            else if (timer != 4'd0)
                timer <= timer - 4'd1;
        end
    end

    // P: after the engine has been armed, the countdown must never be
    //    expired while work is still outstanding in the queue.
    always @(posedge clk)
        assert (!armed || count == 3'd0 || timer != 4'd0);
endmodule

