module split_total_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [5:0] up,
    output reg  [5:0] down,
    output reg  [5:0] maxv
);
    // The workload of TOTAL units is split between a rising share (up) and a
    // remaining share (down); one enable moves exactly one unit across, so the
    // two counters always sum to TOTAL.  maxv tracks the larger of the shares.
    localparam [5:0] TOTAL = 6'd20;

    initial begin
        up   = 6'd0;
        down = TOTAL;
        maxv = TOTAL;
    end

    wire do_step = step && (down != 6'd0);

    wire [5:0] nxt_up   = up   + 6'd1;
    wire [5:0] nxt_down = down - 6'd1;
    wire [5:0] nxt_max  = (nxt_up > nxt_down) ? nxt_up : nxt_down;

    always @(posedge clk) begin
        if (rst) begin
            up   <= 6'd0;
            down <= TOTAL;
            maxv <= TOTAL;
        end else if (do_step) begin
            up   <= nxt_up;
            down <= nxt_down;
            maxv <= nxt_max;
        end
    end

    // P: the larger share can never drop below half of the total.
    always @(*)
        assert (maxv >= 6'd10);
endmodule

