module txn_scoreboard (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire arm_req,
    input  wire start_req,
    input  wire fin_req,
    output wire o_retire,
    output wire [2:0] o_outstanding
);
    // three-step transaction chain: arm -> start -> finish
    // scoreboard counters (monotone, never wrap: arming stops at 4'hf)
    reg [3:0] n_armed;
    reg [3:0] n_started;
    reg [3:0] n_finished;

    // credit registers: armed-not-started, started-not-finished, issued-not-retired
    reg [2:0] cred_start;
    reg [2:0] cred_fin;
    reg [2:0] outst;

    reg retire_pulse;

    initial n_armed     = 4'd0;
    initial n_started   = 4'd0;
    initial n_finished  = 4'd0;
    initial cred_start  = 3'd0;
    initial cred_fin    = 3'd0;
    initial outst       = 3'd0;
    initial retire_pulse = 1'b0;

    localparam [2:0] WINDOW = 3'd4;

    // a new transaction may be armed only inside the outstanding window
    wire arm_fire   = ce && arm_req   && (outst < WINDOW) && (n_armed != 4'hf);
    // a transaction may start only if one has been armed and not yet started
    wire start_fire = ce && start_req && (cred_start != 3'd0);
    // a transaction may finish only if one has been started and not yet finished
    wire fin_fire   = ce && fin_req   && (cred_fin   != 3'd0);

    always @(posedge clk) begin
        if (rst) begin
            n_armed      <= 4'd0;
            n_started    <= 4'd0;
            n_finished   <= 4'd0;
            cred_start   <= 3'd0;
            cred_fin     <= 3'd0;
            outst        <= 3'd0;
            retire_pulse <= 1'b0;
        end else begin
            n_armed    <= n_armed    + (arm_fire   ? 4'd1 : 4'd0);
            n_started  <= n_started  + (start_fire ? 4'd1 : 4'd0);
            n_finished <= n_finished + (fin_fire   ? 4'd1 : 4'd0);

            cred_start <= cred_start + (arm_fire   ? 3'd1 : 3'd0)
                                     - (start_fire ? 3'd1 : 3'd0);
            cred_fin   <= cred_fin   + (start_fire ? 3'd1 : 3'd0)
                                     - (fin_fire   ? 3'd1 : 3'd0);
            outst      <= outst      + (arm_fire   ? 3'd1 : 3'd0)
                                     - (fin_fire   ? 3'd1 : 3'd0);

            retire_pulse <= fin_fire;
        end
    end

    assign o_retire      = retire_pulse;
    assign o_outstanding = outst;

    // P: a retirement can only be observed if the chain arm -> start already happened
    always @(posedge clk)
        if (retire_pulse)
            assert ((n_armed != 4'd0) && (n_started != 4'd0));
endmodule

