// In-flight request tracker: an 8-deep shift register of outstanding
// requests plus a separately maintained count of the set bits, with a
// three-step chain monitor (arm -> start -> finish).
module inflight_chain_monitor (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       issue,   // launch a new request into the pipe
    output wire [1:0] phase,
    output wire       busy
);
    // ---- structural state -------------------------------------------------
    reg [7:0] pipe      = 8'd0;   // one bit per in-flight request slot
    reg [3:0] count     = 4'd0;   // separately maintained popcount of pipe

    // ---- three-step chain monitor ----------------------------------------
    reg       arm_seen  = 1'b0;   // step 1: a request was issued
    reg       start_seen= 1'b0;   // step 2: a request was actually in flight
    reg       fin_seen  = 1'b0;   // step 3: a request retired out of stage 7

    wire ins    = issue;
    wire retire = pipe[7];

    always @(posedge clk) begin
        if (rst) begin
            pipe       <= 8'd0;
            count      <= 4'd0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            fin_seen   <= 1'b0;
        end else if (ce) begin
            pipe  <= {pipe[6:0], ins};
            count <= count + {3'd0, ins} - {3'd0, retire};

            if (ins)            arm_seen   <= 1'b1;
            if (count != 4'd0)  start_seen <= 1'b1;
            if (retire)         fin_seen   <= 1'b1;
        end
    end

    assign phase = fin_seen   ? 2'd3 :
                   start_seen ? 2'd2 :
                   arm_seen   ? 2'd1 : 2'd0;
    assign busy  = (count != 4'd0);

    // ---- property: chain precedence, global scope -------------------------
    // A finish can never be observed unless a start was observed, which can
    // never be observed unless an arm was observed.
    always @(posedge clk)
        assert (!fin_seen || (start_seen && arm_seen));

endmodule

