    wire       vld = |req_q;
    wire [2:0] idx = req_q[7] ? 3'd7 :
                     req_q[6] ? 3'd6 :
                     req_q[5] ? 3'd5 :
                     req_q[4] ? 3'd4 :
                     req_q[3] ? 3'd3 :
                     req_q[2] ? 3'd2 :
                     req_q[1] ? 3'd1 : 3'd0;

