                    st      <= S_HEADER;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                        ready   <= 1'b1;
                    end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                        rows    <= rows + 4'd1;
