        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
       p_occ   = 2'd0;
s_occ   = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
