           cr_lim     <= cr_shrink ? (cr_lim - 4'd1) : cr_lim;
            armed_cr   <= 4'd0;
            busy_cr    <= 4'd0;
            armed_b    <= 4'd0;
            busy_b     <= 4'd0;
            sel        <= 1'b0;
            ever_arm   <= 1'b0;
            ever_start <= 1'b0;
            nf         <= 1'b0;
evt_hist   <= 4'd0;
o_evt_cnt  <= 4'd0;
