module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
    output wire busy
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;
   // governor watermark: deepest outstanding occupancy seen so far
   reg [2:0] peak;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
        svc     = 1'b0;
        timer   = 4'd0;
       peak    = 3'd0;
    end

   // once occupancy has ever peaked at the whole pool, hold off new
   // spends until the consumer has drained completely
   wire throttle  = (peak == TOTAL) && (outst != 3'd0);
   wire do_spend  = req && (credits != 3'd0) && !throttle;
    wire do_return = (outst != 3'd0) && (svc == 1'b1);
   wire [2:0] outst_nxt = outst + (do_spend  ? 3'd1 : 3'd0)
                                - (do_return ? 3'd1 : 3'd0);

    assign grant = i_ce && do_spend;
    assign busy  = (outst != 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
                svc     <= 1'b0;
                timer   <= 4'd0;
               peak    <= 3'd0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
                outst   <= outst   + (do_spend  ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

               // watermark only ever rises
               if (outst_nxt > peak)
                   peak <= outst_nxt;

                // deadline budget: each spend buys 2 cycles, one cycle burnt
                timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0)
                               + (do_spend ? 4'd2 : 4'd0);
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

   // Quiescence (safety): once the whole pool is back at the producer
   // there is nothing left at the consumer, so the service phase must be
   // idle and the deadline budget must be fully spent.
   always @(posedge clk)
       if (credits == TOTAL)
           assert ((timer == 4'd0) && (svc == 1'b0));

   // Governor coherence (safety): the in-flight deadline budget never
   // exceeds two cycles per credit at the recorded peak occupancy.
   always @(posedge clk)
       assert (timer <= {peak, 1'b0});

endmodule

