module token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: nothing moves when low
    input  wire       req,
    output reg        grant_q,
    output reg [3:0]  tokens
);
    localparam [3:0] BURST  = 4'd12; // bucket cap
    localparam [3:0] REFILL = 4'd3;  // tokens added per timer tick
    localparam [2:0] PERIOD = 3'd4;  // refill timer top
   localparam [3:0] SOFT    = 4'd8; // tokens kept in the live bucket
   localparam [3:0] RESVMAX = 4'd6; // reserve pool cap

    reg [2:0] timer;
    reg       saw_refill;            // shadow: a refill tick has occurred
   // Overflow reserve: refill above SOFT is parked here instead of being
   // thrown away by the clamp, and trickles back one token at a time when
   // the live bucket runs dry.
   reg [3:0] resv;

   // Refill commit pipeline: the bucket adder/clamp is registered, so the
   // token target computed at a timer tick is applied four cycles later.
   // Layout of each stage: {valid, precomputed token target}.
   reg [4:0] rf_s1, rf_s2, rf_s3, rf_s4;

    wire       tick     = (timer == PERIOD);
    wire       do_grant = ce && req && (tokens != 4'd0);
    wire [4:0] sum      = {1'b0, tokens} + {1'b0, REFILL};
    wire [3:0] refilled = (sum > {1'b0, BURST}) ? BURST : sum[3:0];
   wire       commit   = rf_s4[4];
   wire [3:0] target   = rf_s4[3:0];
  wire [3:0] eff_target = (target > SOFT) ? SOFT : target;
  wire [3:0] excess     = (target > SOFT) ? (target - SOFT) : 4'd0;
  wire [4:0] resv_sum   = {1'b0, resv} + {1'b0, excess};
  wire       drain      = !commit && (tokens == 4'd0) && (resv != 4'd0);

    initial begin
        timer      = 3'd0;
        tokens     = 4'd0;
        saw_refill = 1'b0;
       resv       = 4'd0;
        grant_q    = 1'b0;
       rf_s1      = 5'd0;
       rf_s2      = 5'd0;
       rf_s3      = 5'd0;
       rf_s4      = 5'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            timer      <= 3'd0;
            tokens     <= 4'd0;
            saw_refill <= 1'b0;
           resv       <= 4'd0;
            grant_q    <= 1'b0;
           rf_s1      <= 5'd0;
           rf_s2      <= 5'd0;
           rf_s3      <= 5'd0;
           rf_s4      <= 5'd0;
        end else if (ce) begin
            timer   <= tick ? 3'd0 : (timer + 3'd1);
            grant_q <= do_grant;

           // stage the refill: capture the clamped target at the tick and
           // walk it down the pipeline, one stage per enabled cycle
           rf_s1 <= {tick, refilled};
           rf_s2 <= rf_s1;
           rf_s3 <= rf_s2;
           rf_s4 <= rf_s3;

            if (tick)
                saw_refill <= 1'b1;

           case ({commit, do_grant})
              2'b10:   tokens <= eff_target;
                2'b01:   tokens <= tokens - 4'd1;
              2'b11:   tokens <= (eff_target == 4'd0) ? 4'd0 : (eff_target - 4'd1);
               default: tokens <= drain ? 4'd1 : tokens;
            endcase

          // reserve bookkeeping: soak up the clamped surplus, or hand one
          // token back to the live bucket when it has emptied out
          if (commit)
              resv <= (resv_sum > {1'b0, RESVMAX}) ? RESVMAX : resv_sum[3:0];
          else if (drain)
              resv <= resv - 4'd1;
        end
    end

    // Precedence: a registered grant can only be observed if a refill tick
    // was recorded earlier in the shadow bit.
    always @(posedge clk)
        if (grant_q)
            assert (saw_refill);

endmodule


