        pv <= 1'b1;

        if (do_issue) begin
            armed  <= 1'b1;
            issued <= issued + 4'd1;
        end

        if (do_retire)
            retired <= retired + 4'd1;

        outst <= outst_n;
       queued <= queued_n;
       qb     <= qb_n;
       if (admit) rr <= admit_a;

        if (do_issue || do_retire) begin
