                        st      <= S_IDLE;
                        loading <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                end
