module csa_accum_parity (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_clear,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
    output wire [7:0] o_ref
);
    // accumulator kept in carry-save form: two halves that always sum to the
    // true running total held in the reference register
    reg [7:0] acc_s = 8'h00;   // sum half
    reg [7:0] acc_c = 8'h00;   // carry half (always even by construction)
    reg [7:0] total = 8'h00;   // plain ripple-carry reference accumulator
    reg        hi_flag = 1'b0; // registered "total has reached the upper half";
                               // precomputed on the adder result so the flush
                               // path next cycle is just a flop-to-mux hop

    wire [7:0] sum_bits   = acc_s ^ acc_c ^ i_data;
    wire [7:0] maj_bits   = (acc_s & acc_c) | (acc_s & i_data) | (acc_c & i_data);
    wire [7:0] carry_bits = {maj_bits[6:0], 1'b0};
    wire [7:0] next_total = total + i_data;

    always @(posedge clk) begin
        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
            total <= 8'h00;
            hi_flag <= 1'b0;
        end else if (i_ce) begin
            if (i_clear || hi_flag) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
                total <= 8'h00;
                hi_flag <= 1'b0;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
                total   <= next_total;
                hi_flag <= next_total[7];
            end
        end
    end

    assign o_total = acc_s + acc_c;
    assign o_ref   = total;

    // P: while the unit is actually accumulating, the low bit of the sum half
    // alone already carries the parity of the true total.
    always @(posedge clk)
        if (i_ce && !i_clear)
            assert (acc_s[0] == total[0]);

    // P2: the flush flag was computed from the adder result, so it must still
    // describe the value the carry-save side is currently reporting.
    always @(posedge clk)
        assert (hi_flag == o_total[7]);
endmodule

