reg [3:0] mw_cls;
// saturation full-detect, sampled when the credit is posted so the
// 15-compare sits off the lock path; the lock engages when the armed
// credit retires one enabled cycle later
reg       lock_arm;

    initial prog        = 3'd0;
    initial saw_p3      = 1'b0;
    initial match_count = 4'd0;
   initial cmt_vld     = 1'b0;
  initial sat_lock    = 1'b0;
 initial drop_cnt    = 4'd0;
initial post_cnt    = 4'd0;
initial rtr_cnt     = 4'd0;
initial mw_opn      = 4'd0;
initial mw_cls      = 4'd0;
initial lock_arm    = 1'b0;

    // pattern bit expected next (safe index for prog 0..3)
    wire [1:0] idx      = 2'd3 - prog[1:0];
    wire       exp_bit  = PAT[idx];
