module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

   // The binary->gray conversion is pipelined: the encoder runs one
// increment ahead of the visible counter; behind it a four-deep
// prefetch chain holds the next four encodings, so the adder and the
// XOR network run six counts ahead and every register in the chain --
// including the output register -- is fed straight out of a register.
reg [2:0] gray_pre;     // in-flight gray code for bin+1, low bits
// Bit 3 of a gray code is just bit 3 of the binary count, so the top
// bit skips the XOR network entirely and lives in its own register.
// It is only reloaded on the two counts where it can change, which
// keeps it from toggling with the rest of the pipeline.
reg       gray_pre_top;
// prefetch chain: pre-encoded gray codes waiting to be shifted into
// the stage-1 registers, oldest (nearest the output) first.
reg [3:0] gray_pre2;    // gray code queued for bin+2
reg [3:0] gray_pre3;    // gray code queued for bin+3
reg [3:0] gray_pre4;    // gray code queued for bin+4
reg [3:0] gray_pre5;    // gray code queued for bin+5

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
   reg [3:0] goal_pre;   // deadline gray code, encoded K counts ahead
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
gray_pre     = 3'd1;   // encoder prefilled with gray(bin+1)[2:0]
gray_pre_top = 1'b0;   // ... and its top bit
gray_pre2    = 4'd3;   // prefetch chain prefilled with gray(bin+2..5)
gray_pre3    = 4'd2;
gray_pre4    = 4'd6;
gray_pre5    = 4'd7;
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
       goal_pre  = 4'd12;   // gray(0 + K)
        armed     = 1'b0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
   wire [3:0] bin_ahead  = bin_nxt + 4'd1;
// deepest lookahead: the count whose encoding enters the chain now
wire [3:0] bin_la     = bin + 4'd6;
wire [3:0] gray_la    = bin_la ^ (bin_la >> 1);
// the held top bit only needs a new value as the count rolls into 8 or 0
wire       top_load  = (bin_ahead[2:0] == 3'd0);

// The deadline encoder runs alongside the counter so the accept path
// does not have to carry an adder and an XOR network in the same
// cycle: goal_pre always holds the code the counter will show K
// counts from now, and accept just latches it.
wire [3:0] goal_bin      = bin_nxt + K;
wire [3:0] goal_gray_nxt = goal_bin ^ (goal_bin >> 1);

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
gray_pre  <= gray_pre2[2:0];
if (top_load) gray_pre_top <= gray_pre2[3];
gray     <= {gray_pre_top, gray_pre};
// the prefetch chain shifts one encoding per count
gray_pre2 <= gray_pre3;
gray_pre3 <= gray_pre4;
gray_pre4 <= gray_pre5;
gray_pre5 <= gray_la;
           // deadline encoder keeps pace with the counter
           goal_pre <= goal_gray_nxt;

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
               goal_gray <= goal_pre;
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));

   // P2: the on-time flag marks the deadline count itself -- the
   // tracked request is due exactly when the counter reaches the
   // latched goal code.
   always @(posedge clk)
       assert (o_on_time == (busy && (timer == 4'd1)));
endmodule

