module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
