if (adv) begin
pipe <= {pipe[1:0], acc};
wb   <= pipe[2];
occ    <= occ    + (acc ? 3'd1 : 3'd0) - (wb ? 3'd1 : 3'd0);
// a drained ledger means the pool owes nothing: re-sync it to full
credit <= drained ? (3'd4 - (acc ? 3'd1 : 3'd0))
                  : (credit - (acc ? 3'd1 : 3'd0) + (wb ? 3'd1 : 3'd0));
