    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
   initial ret_p   = 2'd0;
    initial out_r   = 4'd0;
   initial sec_iss = 5'd0;
   initial sec_ret = 5'd0;
   initial out_s   = 4'd0;
   initial rr      = 1'b0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
   initial iss_d1  = 5'd0;
   initial iss_d2  = 5'd0;
   initial iss_d3  = 5'd0;
   initial iss_d4  = 5'd0;
    initial mon     = 1'b0;
    initial pv      = 1'b0;
initial o_act   = 4'd0;

