        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
           ret_p <= 2'd0;
            out_r <= 4'd0;
           sec_iss <= 5'd0;
           sec_ret <= 5'd0;
           out_s   <= 4'd0;
           rr      <= 1'b0;
o_act <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
           if (acc_iss_s) sec_iss <= sec_iss + 5'd1;
           if (acc_ret_s) sec_ret <= sec_ret + 5'd1;
           if (iss_any)   rr <= ~rr;
