               ret   <= ret + {3'b0, ret_p} + (acc_ret ? 5'd1 : 5'd0);
               ret_p <= 2'd0;
           end else if (acc_ret) begin
               if (ret_p == 2'd3) begin
                   ret   <= ret + 5'd4;
                   ret_p <= 2'd0;
               end else begin
                   ret_p <= ret_p + 2'd1;
               end
           end
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
           if (acc_iss_s && !acc_ret_s)
               out_s <= out_s + 4'd1;
           else if (!acc_iss_s && acc_ret_s)
               out_s <= out_s - 4'd1;
if (i_ce && (i_open || i_close))
    o_act <= o_act + 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
           iss_d1  <= 5'd0;
           iss_d2  <= 5'd0;
           iss_d3  <= 5'd0;
           iss_d4  <= 5'd0;
        end else if (i_ce) begin
           full_q  <= (occ == {1'b0, WINDOW});
