    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

   // second (tail) skid slot: lets the stage swallow one more word when the
   // consumer stalls for two cycles in a row instead of dropping in_ready
   // immediately behind a single buffered word
   reg       skid2_valid = 1'b0;
   reg [1:0] skid2_code  = ARM;

   // one-cycle inter-chain gap: after a FINISH leaves the stage the
   // producer is held off for a cycle so it can resynchronise on the
   // head of the next chain
   reg       gap        = 1'b0;

  // purely observational: count of words handed to the consumer
  reg [3:0] fire_count = 4'd0;

    wire [1:0] in_code  = src_phase + 2'd1;
  wire       in_ready = !skid2_valid && !gap;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;
   assign o_fire_count = fire_count;

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
           skid2_valid <= 1'b0;
           skid2_code  <= ARM;
           gap        <= 1'b0;
          fire_count <= 4'd0;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
               end else if (in_valid && in_ready) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
               if (out_room) begin
                   // head drains into the output register; refill it from
                   // the tail slot, or straight from the producer
                   if (skid2_valid) begin
                       skid_valid <= 1'b1;
                       skid_code  <= skid2_code;
                   end else if (in_valid && in_ready) begin
                       skid_valid <= 1'b1;
                       skid_code  <= in_code;
                   end else begin
                       skid_valid <= 1'b0;
                   end
               end
           end else if (in_valid && in_ready && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

           // tail slot: only fills behind a full head slot while the
           // output register is blocked, and always shifts down on a drain
           if (skid2_valid) begin
               if (out_room)
                   skid2_valid <= 1'b0;
           end else if (in_valid && in_ready && skid_valid && !out_room) begin
               skid2_valid <= 1'b1;
               skid2_code  <= in_code;
           end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

            // consumer chain tracker advances on every delivered word
            if (out_valid && out_ready)
                phase <= (out_code == FINISH) ? 2'd0 : out_code;

           // hold the producer off for one cycle after a completed chain
           gap <= out_valid && out_ready && out_code == FINISH;

          if (out_valid && out_ready)
              fire_count <= fire_count + 4'd1;
