   // ---- distractor: rolling record of request pulses ---------------
   reg [3:0] req_hist;

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
gray_pre     = 3'd1;   // encoder prefilled with gray(bin+1)[2:0]
gray_pre_top = 1'b0;   // ... and its top bit
gray_pre2    = 4'd3;   // prefetch chain prefilled with gray(bin+2..5)
gray_pre3    = 4'd2;
gray_pre4    = 4'd6;
gray_pre5    = 4'd7;
