module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

   // saved context of the decode channel that is parked while the other
   // one owns the shared pipeline slot
   reg  [3:0] count_sh;
   reg        exp_sh;
  // second parked context: three decode channels rotate through the one
  // pipeline slot, so two of them are always parked at any time
  reg  [3:0] count_sh2;
  reg        exp_sh2;
 // remaining slack of the channel that currently owns the slot; the
 // timeout now fires on a zero-detect of this countdown instead of a
 // magnitude compare, and it is reloaded whenever the slot changes hands
 reg  [3:0] deadline;
// the decode channel hands its shared operand port to the issue stage for
// one pipeline advance on every successful decode; the port comes back on
// the following advance.  both sides of the loan are logged so the loan
// traffic can be watched from the outside, and the level flag is the
// registered "port is out" condition used by the slack report.
reg  [3:0] n_lend;    // hand-overs to the issue stage (wraps)
reg  [3:0] n_back;    // returns from the issue stage (wraps)
reg        port_out;  // the operand port is out on loan right now
// the issue stage hands the operand port back together with the result of
// the decoded instruction; that result is parked in the one-entry commit
// slot until the commit stage accepts it on the following advance.  both
// sides of the parking are logged so commit traffic is visible outside.
reg  [3:0] n_post;   // results parked in the commit slot (wraps)
reg  [3:0] n_pop;    // results accepted by the commit stage (wraps)
reg        rb_full;  // a result is parked in the commit slot right now

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
       count_sh = 4'd0;
       exp_sh   = 1'b0;
      count_sh2 = 4'd0;
      exp_sh2   = 1'b0;
     deadline  = LIMIT;
n_lend    = 4'd0;
n_back    = 4'd0;
port_out  = 1'b0;
n_post    = 4'd0;
n_pop     = 4'd0;
rb_full   = 1'b0;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

   // the slot is handed to the other channel when the active one makes
   // progress, and is preempted once the active one has clearly hung
// a preemption is deferred while a result is still parked for commit,
// because rotating the slot would orphan the parked result
wire swap = kick || (count == LIMIT && !rb_full);

  // the channel holding the slot has just run out of slack
  wire hung = !kick && (deadline <= 4'd1);

// a decode hands the port over unless it is already out; the return
// ledger chases the hand-over ledger, so the port comes back on the next
// advance after it was taken
wire       lend      = !port_out && kick;
wire       back      = (n_lend != n_back);
wire [3:0] n_lend_nx = n_lend + (lend ? 4'd1 : 4'd0);
wire [3:0] n_back_nx = n_back + (back ? 4'd1 : 4'd0);
wire       port_nx   = lend || (port_out && !back);
// the commit slot takes the result on the advance the port comes back and
// the commit stage drains it on the advance after that
wire       rb_take   = back;
wire       rb_free   = (n_post != n_pop);
wire       rb_nx     = rb_take || (rb_full && !rb_free);
wire [3:0] n_post_nx = n_post + (rb_take ? 4'd1 : 4'd0);
wire [3:0] n_pop_nx  = n_pop  + (rb_free ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
           count_sh <= 4'd0;
           exp_sh   <= 1'b0;
           count_sh2 <= 4'd0;
           exp_sh2   <= 1'b0;
          deadline  <= LIMIT;
n_lend    <= 4'd0;
n_back    <= 4'd0;
port_out  <= 1'b0;
n_post    <= 4'd0;
n_pop     <= 4'd0;
rb_full   <= 1'b0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
           if (swap) begin
               count    <= count_sh;         // resume the parked channel
              deadline <= LIMIT - count_sh; // slack left for the resumed channel
count_sh  <= count_sh2;        // rotate the parked queue forward
count_sh2 <= nxt;              // park the current stall count
exp_sh    <= exp_sh2;          // its hang flag rotates with it
exp_sh2   <= hung;             // remember if it hung
           end else begin
               count    <= nxt;
              deadline <= (deadline == 4'd0) ? 4'd0 : deadline - 4'd1;
           end
// the loan ledgers are free running and wrap at four bits; nothing but
// the flag tracks how many loans are outstanding
if (lend) n_lend <= n_lend + 4'd1;
if (back) n_back <= n_back + 4'd1;
port_out <= port_nx;
// the commit ledgers are free running and wrap at four bits
n_post   <= n_post_nx;
n_pop    <= n_pop_nx;
rb_full  <= rb_nx;
           // sticky per channel: a kick only clears the channel that
           // currently owns the slot
// the hang detector reads the ledgers directly: a hand-over that is
// still unmatched means the issue stage never took the operands
// and a result that is still parked for commit stalls the channel too
expired <= hung || exp_sh || exp_sh2 || (n_lend_nx != n_back_nx) || rb_nx;
// the slack report is built from the registered port flag
healthy <= (nxt < WARN) && (count_sh < WARN) && (count_sh2 < WARN) && !port_nx
           && (n_post_nx == n_pop_nx);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

