reg [3:0] act;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
      cnt2 = 4'd0;
      g2   = 4'd0;
      ph   = 1'b0;
     cnt3 = 4'd0;
     g3   = 4'd0;
     own  = 3'b001;
act   = 4'd0;
o_act = 4'd0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
