    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
        rtn  <= 3'd0;
mrg  <= 1'b0;
mg0  <= 1'b0;
mg1  <= 1'b0;
mg2  <= 1'b0;
mg3  <= 1'b0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
            rtn  <= 3'd0;
mrg  <= 1'b0;
mg0  <= 1'b0;
mg1  <= 1'b0;
mg2  <= 1'b0;
mg3  <= 1'b0;
        end else begin
cred <= cred - {2'b00, accept} + {2'b00, mg3};
            rtn  <= rtn + {2'b00, rq3} - {2'b00, drain};
mrg  <= drain;
mg0  <= mrg;
mg1  <= mg0;
mg2  <= mg1;
mg3  <= mg2;
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

