    initial outst = 4'd0;
initial stage = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;
initial n_spend = 4'd0;
initial n_ret = 4'd0;
initial phase = 1'b0;
initial rdy = 1'b0;
initial n_grant = 4'd0;
initial n_use = 4'd0;
initial sready = 1'b0;
initial n_stg = 4'd0;
initial n_lnch = 4'd0;
