    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
   initial pend     = 2'd0;
   initial pend_sel = 2'd0;
  initial fq     = 4'd0;
  initial fq_sel = 2'd0;
