  wire req2 = (nxt2 == 3'd2);
  wire gnt1 = req1 && (!req2 || !harb);
  wire gnt2 = req2 && (!req1 ||  harb);

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

   always @(*) begin
       case (prog2)
           3'd0: nxt2 = sym ? 3'd0 : 3'd1;
           3'd1: nxt2 = sym ? 3'd2 : 3'd1;
           3'd2: nxt2 = sym ? 3'd0 : 3'd3;
           3'd3: nxt2 = sym ? 3'd2 : 3'd0;  // overlap: "01" survives
           default: nxt2 = 3'd0;
       endcase
   end

    always @(posedge clk) begin
        if (i_ce) begin
          // the retire pipeline advances one hop on every tick
          cm1 <= stg;   cn1 <= stg2;   cv1 <= stg_v;
          cm2 <= cm1;   cn2 <= cn1;    cv2 <= cv1;
          cm3 <= cm2;   cn3 <= cn2;    cv3 <= cv2;
          cm4 <= cm3;   cn4 <= cn3;    cv4 <= cv3;
          if (cv4) begin
              // retire phase: the value that has walked the whole pipeline
              // lands in the two matchers
              prog      <= cm4;
              prog2     <= cn4;
              if (cm4 == 3'd0)
                  seen_half <= 1'b0;   // white matcher restarted
          end
          if (idle) begin
               // decode phase: consume the press, stage the new progress
               stg       <= nxt;
              stg2      <= nxt2;
               stg_v     <= 1'b1;
               seen_half <= seen_half | (nxt == 3'd2);
             if ((gnt1 || gnt2) && (hcnt != 3'd7))
                 hcnt <= hcnt + 3'd1;
             // whichever half-way pass lost the port is owed an increment
             hpend     <= (req1 && !gnt1) || (req2 && !gnt2);
             if (req1 && req2)
                 harb <= ~harb;
              // the alarm sounds on the pattern match, and also on the press
              // that takes the black-turn tally to its limit
             alarm     <= match | match2 |
                          ((gnt1 || gnt2) && (hcnt == 3'd6));
               if (match)
                   before_alarm <= 1'b0;
          end else if (stg_v) begin
              // commit phase: the staged press is handed to the retire
              // pipeline, so the tally adder is free for the owed increment
               stg_v     <= 1'b0;
             // the owed increment retires now that the adder is idle
             if (hpend && (hcnt != 3'd7))
                 hcnt <= hcnt + 3'd1;
             hpend     <= 1'b0;
             alarm     <= hpend && (hcnt == 3'd6);
           end
          else begin
              // the retire pipeline is still draining: no new alarm source
              alarm     <= 1'b0;
          end
        end
    end

    // Precedence, in the scope before the alarm has ever fired:
    // three-quarter progress can only be observed if half progress happened earlier.
    always @(posedge clk)
        assert (!before_alarm || (prog != 3'd3) || seen_half);

   // Tally accounting, in the scope before the alarm has ever fired:
   // three-quarter progress cannot be on record while the black-turn tally
   // is still empty, because reaching it costs one black press.
   always @(posedge clk)
       assert (!before_alarm || (prog != 3'd3) || (hcnt != 3'd0));
endmodule

