        if (rst) begin
            stall    <= 1'b0;
            skid      <= 4'h0;
            skid_hi   <= 4'h0;
            skid_wide <= 1'b0;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
