// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
// accumulator port credit ledger: each accepted advance issues one
// increment request, the commit stage retires one per enabled cycle.
// Both counters free-run and wrap at four bits.
reg [3:0] n_iss, n_cmt;
// the shared increment port stays busy while a credit is unretired
wire      port_busy = (n_iss != n_cmt);
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;
   // stage-2 drain chain: reuses the same handshake strobes once stage 1 retired
   reg [2:0] ph_ref2;
   // sticky flag: the drain chain reached its final phase
   reg       b_done;
  // stage-3 writeback chain: reuses the same strobes after the drain retired
  reg [2:0] ph_ref3;
  // sticky flag: the writeback chain reached its final phase
  reg       c_done;

 // retire threshold: how many handshake steps a stage must complete before it
 // releases the shared increment port to the next stage. The host selects the
 // short (arm/start only) protocol by presenting i_finish with the track event.
 reg [2:0] lim;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
n_iss      = 4'd0;
n_cmt      = 4'd0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
       ph_ref2    = 3'd0;
       b_done     = 1'b0;
      ph_ref3    = 3'd0;
      c_done     = 1'b0;
     lim        = 3'd3;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
// report the committed total plus the credit still in flight
assign o_total = total + {3'd0, port_busy};
  assign o_done  = (total == 4'd3) || b_done || c_done;

    // one chain step at a time, in order
wire adv = i_ce && !port_busy && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

   // the drain chain may only take the shared accumulator once stage 1 retired
wire adv2 = i_ce && !port_busy && (ph_ref >= lim) && !adv &&
                       (((ph_ref2 == 3'd0) && i_arm)   ||
                        ((ph_ref2 == 3'd1) && i_start) ||
                        ((ph_ref2 == 3'd2) && i_finish));

  // the writeback chain only takes the shared accumulator once the drain retired
wire adv3 = i_ce && !port_busy && (ph_ref2 >= lim) && !adv && !adv2 &&
                      (((ph_ref3 == 3'd0) && i_arm)   ||
                       ((ph_ref3 == 3'd1) && i_start) ||
                       ((ph_ref3 == 3'd2) && i_finish));

   // shared increment port into the carry-save halves
  wire inc = adv || adv2 || adv3;

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
n_iss      <= 4'd0;
n_cmt      <= 4'd0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
           ph_ref2    <= 3'd0;
           b_done     <= 1'b0;
          ph_ref3    <= 3'd0;
          c_done     <= 1'b0;
         lim        <= 3'd3;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

           // the retire threshold is only re-programmed between runs, while
           // stage 1 is still idle
           if (i_ce && i_track && (ph_ref == 3'd0))
               lim <= i_finish ? 3'd2 : 3'd3;

// issue side of the ledger: one credit per accepted advance
if (inc)
    n_iss <= n_iss + 4'd1;

// commit side: the outstanding credit lands in the halves; the parity
// of the commit count picks which half receives it
if (i_ce && port_busy) begin
    if (n_cmt[0]) acc_b <= acc_b + 3'd1;
    else          acc_a <= acc_a + 3'd1;
    n_cmt <= n_cmt + 4'd1;
