            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            queued     <= 4'd0;
           chunk_pend <= 4'd0;
           n_iss      <= 4'd0;
           n_ret      <= 4'd0;
o_ce_count <= 4'd0;
            busy       <= 1'b0;
