module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
output reg  [3:0] count,
output reg  [7:0] o_push_tally,
output reg  [3:0] o_op_shadow
