    reg [1:0] draw_cnt;
    reg       cleared_seen;   // shadow: framebuffer was cleared this frame
   reg [1:0] ov_state;      // overlay plane pipeline
   reg       ov_pend;       // overlay refresh owed after the last frame
reg [2:0] fb_cmd;        // framebuffer update in flight to the shadow
reg [1:0] cur_state;     // hardware cursor plane pipeline
reg       cur_pend;      // cursor repaint owed after the last frame

