                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                   ov_pend      <= 1'b1;   // overlay gets the buffer next
