              CU_FETCH: begin
                  cur_state <= CU_PAINT;
                  draw_cnt  <= 2'd0;
              end
              CU_PAINT: begin
                  if (draw_cnt == 2'd2)
                      cur_state <= CU_DONE;
                  else
                      draw_cnt <= draw_cnt + 2'd1;
