                              // ack rose: snapshot the response route
                              phase  <= 2'd2;
                              ack    <= 1'b1;
                              resp_a <= own_a;
                              resp_b <= own_b;
                          end
                    2'd2: begin
                              // req may only drop now that ack is high
                              phase <= 2'd3;
                              req   <= 1'b0;
                          end
                    2'd3: if (!i_ack_in) begin
                              phase  <= 2'd0;
                              ack    <= 1'b0;
                              busy   <= 1'b0;
                            rel_pend <= 1'b1;
                              own_a  <= 1'b0;
                              own_b  <= 1'b0;
                              resp_a <= 1'b0;
                              resp_b <= 1'b0;
                              virgin <= 1'b0;   // first completion disarms
                          end
                    default: ;
                endcase
