   initial gnt_a = 1'b0;
   initial gnt_b = 1'b0;
   initial gnt_take = 1'b0;
   initial p1_a = 1'b0;
   initial p1_b = 1'b0;
   initial p1_take = 1'b0;
   initial p2_a = 1'b0;
   initial p2_b = 1'b0;
   initial p2_take = 1'b0;
   initial p3_a = 1'b0;
   initial p3_b = 1'b0;
