module wdog_scan (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // scanner step enable; low => whole design idles
    input  wire i_kick,    // full substring match: hard kick of the watchdog
    input  wire i_feed,    // partial match: partial credit, no flag clear
    output wire o_timeout,
    output wire [7:0] o_pos
);
    // Watchdog for a character-scan engine: the scanner must report progress
    // before LIMIT idle steps elapse, otherwise the search is declared timed out.
    localparam [3:0] LIMIT = 4'd12;

    reg [3:0] wd;       // cycles since last progress, saturates at LIMIT
    reg       expired;  // sticky timeout flag
    reg [7:0] pos;      // current character position in the haystack
    reg [3:0] slack;    // remaining scan budget exported to the prefetch stride
   // The counter maths sits in the scan pipeline's ALU stage: credit, spend and
   // saturate land here first and are committed onto the report bus (the two
   // registers above) on the following scan step.
   reg [3:0] wd_s;     // watchdog count, arithmetic stage
   reg [3:0] slack_s;  // scan budget, arithmetic stage
    // The timeout flag sits on the report bus, four scan steps downstream of
    // the counter, so a saturation event is registered through this pipe
    // before it is visible to the host.
    reg       exp_s0;   // expiry report, stage 0
    reg       exp_s1;   // expiry report, stage 1
    reg       exp_s2;   // expiry report, stage 2
    reg       exp_s3;   // expiry report, stage 3

    initial wd      = 4'd0;
    initial expired = 1'b0;
    initial pos     = 8'd0;
    initial slack   = LIMIT;
   initial wd_s    = 4'd0;
   initial slack_s = LIMIT;
    initial exp_s0  = 1'b0;
    initial exp_s1  = 1'b0;
    initial exp_s2  = 1'b0;
    initial exp_s3  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            wd      <= 4'd0;
            expired <= 1'b0;
            pos     <= 8'd0;
            slack   <= LIMIT;
           wd_s    <= 4'd0;
           slack_s <= LIMIT;
            exp_s0  <= 1'b0;
            exp_s1  <= 1'b0;
            exp_s2  <= 1'b0;
            exp_s3  <= 1'b0;
        end else if (i_ce) begin
            // plenty of budget left => the scanner may consume two
            // characters in a single step
            pos <= pos + ((slack > 4'd8) ? 8'd2 : 8'd1);
           // commit the previous step's arithmetic onto the report bus
           wd    <= wd_s;
           slack <= slack_s;
            // walk the report pipe one stage per scan step; nothing new
            // enters unless the counter saturates this step
            exp_s0 <= 1'b0;
            exp_s1 <= exp_s0;
            exp_s2 <= exp_s1;
            exp_s3 <= exp_s2;
            if (exp_s3)
                expired <= 1'b1;
            if (i_kick) begin
                // full match: reload the watchdog and drop the timeout flag
                wd      <= 4'd0;
                expired <= 1'b0;
                slack   <= LIMIT;
               wd_s    <= 4'd0;
               slack_s <= LIMIT;
                // the reload also flushes any report still in flight
                exp_s0  <= 1'b0;
                exp_s1  <= 1'b0;
                exp_s2  <= 1'b0;
                exp_s3  <= 1'b0;
            end else if (i_feed) begin
                // partial credit: only granted while the counter has not
                // saturated.  Note the gate looks at the COUNTER, not the flag.
               if (wd_s != LIMIT)
                   wd_s <= (wd_s > 4'd4) ? (wd_s - 4'd4) : 4'd0;
                // partial credit also refunds budget, capped at the reload value
               if (slack_s != 4'd0)
                   slack_s <= (slack_s < 4'd8) ? (slack_s + 4'd4) : LIMIT;
            end else begin
                // no progress this step: count up and saturate at LIMIT
               if (wd_s != LIMIT) begin
                   wd_s <= wd_s + 4'd1;
                   if ((wd_s + 4'd1) == LIMIT)
                        exp_s0 <= 1'b1;
                end
                // spend one unit of budget per idle step, floor at zero
               if (slack_s != 4'd0)
                   slack_s <= slack_s - 4'd1;
            end
        end
    end

    assign o_timeout = expired;
    assign o_pos     = pos;

    // P: a reported timeout always comes with a counter in the top half of
    // its range (the watchdog really did run out of slack).
    always @(posedge clk) assert (!expired || wd[3]);

    // Q: a reported timeout means the exported scan budget is exhausted,
    // so downstream stride logic has already dropped back to one char/step.
    always @(posedge clk) assert (!expired || slack == 4'd0);
endmodule

