    always @(posedge i_clk) begin
        if (i_rst) begin
            grant <= 4'b0000;
            lock  <= 1'b0;
            occ   <= 3'd0;
            hold_cnt <= 3'd0;
           tail_cnt <= 2'd0;
           drn <= 1'b0;
