  // crosses up into the deep region, one exit each time it drops back out
  reg [3:0] n_ent;
  reg [3:0] n_ext;

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial mark_deep = 1'b0;
    initial pv        = 1'b0;
   initial n_push    = 4'd0;
   initial n_pop     = 4'd0;
  initial n_ent     = 4'd0;
  initial n_ext     = 4'd0;

    wire do_push = i_ce && i_push && !i_pop && (sp != 4'hF);
    wire do_pop  = i_ce && i_pop  && !i_push && (sp != 4'h0);

    wire [3:0] sp_nx  = do_push ? (sp + 4'd1)
                      : (do_pop ? (sp - 4'd1) : sp);

   wire [3:0] n_push_nx = do_push ? (n_push + 4'd1) : n_push;
   wire [3:0] n_pop_nx  = do_pop  ? (n_pop  + 4'd1) : n_pop;

   // occupancy as seen by the ledger after this cycle's events
   wire [3:0] occ_nx    = n_push_nx - n_pop_nx;

  wire ent_evt = do_push && (sp == (THRESH - 4'd1));
  wire ext_evt = do_pop  && (sp == THRESH);

  wire [3:0] n_ent_nx = ent_evt ? (n_ent + 4'd1) : n_ent;
  wire [3:0] n_ext_nx = ext_evt ? (n_ext + 4'd1) : n_ext;

  // an episode is open while the entry and exit logs disagree; for the
  // whole episode the mark reserves one guard slot above the threshold
  wire       deep_open = (n_ent != n_ext);
  wire [3:0] guard     = deep_open ? (THRESH + 4'd1) : 4'd0;

