module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
   // per-nibble parity: p0/p1 cover bits [3:0] and the h companions bits [7:4],
   // so a reported mismatch localises the fault to one half-word
   reg       p0h, p1h;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

   // egress check: the word presented on the output register keeps its slice
   // slot for one more cycle while its parity is re-checked, so the credit is
   // returned one cycle after the word leaves
   reg       oq_busy;
   reg       oq_par;
  reg       oq_parh;
// egress lane tag: the word parked in the egress re-check slot keeps its
// credit in the counter of the lane that owns it, so the data lane and the
// echo lane are metered independently instead of swapping credits
reg       eg_sb;
reg [2:0] eg_occ;

  // sideband echo lane: a control word tagged with bit 6 is parked here and
  // replayed onto the output whenever the data lane's second stage is empty.
  // It draws its slot from the same occupancy pool as the data lane.
  reg [7:0] sb_d;
  reg       sb_p;
 reg       sb_ph;
  reg       sb_v;
 // the echo lane leases its slot on a dedicated credit counter, so a parked
 // control word does not disturb the data-lane accounting; the credit is
// handed to the egress counter eg_occ when the parked word takes the slot
 reg [2:0] sb_occ;

   // programmable slot limit (one or two stages), written by a control word
   reg [2:0] lim;

  // replay bookkeeping: every parity mismatch books one replay slot, and a
  // booked slot is handed back when the egress re-check frees a credit
  reg [2:0] rpy;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
       p0h = 1'b0; p1h = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
       oq_busy = 1'b0;
       oq_par  = 1'b0;
      oq_parh = 1'b0;
      eg_sb   = 1'b0;
      eg_occ  = 3'd0;
       sb_d = 8'h00; sb_p = 1'b0; sb_v = 1'b0;
      sb_ph = 1'b0;
     sb_occ  = 3'd0;
       lim     = 3'd2;
      rpy     = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
   wire mism0 = v0 && ((p0 != (^d0[3:0])) || (p0h != (^d0[7:4])));
   wire mism1 = v1 && ((p1 != (^d1[3:0])) || (p1h != (^d1[7:4])));
wire mismsb = sb_v && ((sb_p != (^sb_d[3:0])) || (sb_ph != (^sb_d[7:4])));
wire retry  = mism0 || mism1 || mismsb;

   // the slot is only released when the egress parity re-check is clean
  wire oq_bad = oq_busy && ((oq_par != (^o_data[3:0])) || (oq_parh != (^o_data[7:4])));
   wire rel    = oq_busy && !oq_bad;

   // control words carry the depth limit instead of payload
   wire cfg  = i_valid && i_data[7];
// both lanes draw from the same physical pool, so all three credit counters
// are summed before the depth limit is applied
wire [4:0] pool = {2'b0, occ} + {2'b0, sb_occ} + {2'b0, eg_occ};
wire room = pool < {2'b0, lim};
   wire acc  = i_valid && !cfg && room;
   wire nack = i_valid && !cfg && !room;
  // echo lane arbitration: the parked word only reaches the egress slot when
  // the data lane's second stage is empty, so the lanes never collide
  wire echo    = cfg && i_data[6];
  wire sb_acc  = echo && !sb_v && room;
  wire sb_nack = echo && (sb_v || !room);
  wire sb_go   = sb_v && !v1;

    always @(posedge clk) begin
        if (i_ce) begin
o_retry <= retry || nack || sb_nack || oq_bad || (rpy != 3'd0);
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
               rpy <= rpy + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
               p1h <= p0h;
                v1 <= v0;
                d0 <= i_data;
               p0  <= ^i_data[3:0];
               p0h <= ^i_data[7:4];
               v0 <= acc;
oq_busy <= v1 || sb_go;
oq_par  <= v1 ? p1 : sb_p;
oq_parh <= v1 ? p1h : sb_ph;
eg_sb   <= !v1 && sb_go;
sb_v <= sb_acc || (sb_v && !sb_go);
if (sb_acc) begin
    sb_d <= i_data;
   sb_p  <= ^i_data[3:0];
   sb_ph <= ^i_data[7:4];
end
if (cfg && !echo) lim <= i_data[0] ? 3'd2 : 3'd1;
occ    <= occ + (acc ? 3'd1 : 3'd0) - ((rel && !eg_sb) ? 3'd1 : 3'd0);
eg_occ <= eg_occ + (sb_go ? 3'd1 : 3'd0) - ((rel && eg_sb) ? 3'd1 : 3'd0);
sb_occ <= sb_occ + (sb_acc ? 3'd1 : 3'd0) - (sb_go ? 3'd1 : 3'd0);
              if (rel && rpy != 3'd0) rpy <= rpy - 3'd1;
o_valid <= v1 || sb_go;
o_data  <= v1 ? d1 : sb_d;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);

   // a replay slot is only booked on a real corruption, so booked slots plus
   // live slice slots never oversubscribe the two-deep slice
   always @(posedge clk)
       assert ({1'b0, occ} + {1'b0, rpy} <= 4'd2);
endmodule

