        if (rst) begin
            count   <= 4'd0;
           count_sh <= 4'd0;
           exp_sh   <= 1'b0;
           count_sh2 <= 4'd0;
           exp_sh2   <= 1'b0;
          deadline  <= LIMIT;
n_lend    <= 4'd0;
n_back    <= 4'd0;
port_out  <= 1'b0;
n_post    <= 4'd0;
n_pop     <= 4'd0;
rb_full   <= 1'b0;
cmt_q     <= 1'b0;
            expired <= 1'b0;
            healthy <= 1'b1;
