        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
          gq  <= lane;
           s1  <= gq;
            s2  <= s1;
          ph  <= ~ph;
          if (tick2) begin
              cnt2 <= nxt2;
              g2   <= nxt_gray2;
          end
         if (tick3) begin
             cnt3 <= nxt3;
             g3   <= nxt_gray3;
         end
