          peak_q <= 2'd0;
         hwm_b    <= 2'd0;
         peak_sel <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
           vb0   <= 1'b0;
           vb1   <= 1'b0;
           cntb  <= 2'd0;
           b0    <= 8'h00;
           b1    <= 8'h00;
          sv    <= 1'b0;
          sd    <= 8'h00;
