module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
output wire [2:0] o_count,
output reg [3:0] o_push_tally
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;
   // Skid slot behind the tail.  o_full is raised as soon as the tail fills,
   // but one upstream beat may already be in flight, so it is absorbed here
   // and handed to the tail as soon as a pop frees it.
   reg       s_v;
   reg [7:0] s_d;
  // A second skid slot behind the first, so two beats that were already in
  // flight when full was reported can both be absorbed.  Both slots are
  // accounted for by the shared skid occupancy counter below.
  reg       s2_v;
  reg [7:0] s2_d;
 // A third skid stage, for the deepest case of three beats already in
 // flight when full was reported.  All three stages share the skid
 // occupancy counter and the free-stage credit below.
 reg       s3_v;
 reg [7:0] s3_d;
 // stages still free in the skid.  The accept term sits on the push path,
 // so it reads this counter instead of gathering the three stage flags.
 reg [1:0] sk_credit;
  // occupancy contributed by the skid slot, held apart from the core count
  reg [1:0] skid_occ;
 // the occupancy adder is retimed off the push path: a beat that has just
 // been written into a core slot has its unit of occupancy parked in
 // inc_pend for one cycle and is folded into count on the next edge
 reg       inc_pend;
// the skid-to-core hand-off is retimed the same way: the occupancy that
// leaves the skid counter on a drain is parked here for one cycle before it
// is folded into count
reg [1:0] xfer_pend;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;
  initial s2_v  = 1'b0;
  initial s2_d  = 8'h00;
 initial s3_v  = 1'b0;
 initial s3_d  = 8'h00;
 initial sk_credit = 2'd3;
  initial skid_occ = 2'd0;
 initial inc_pend = 1'b0;
initial xfer_pend = 2'd0;
