module histogram_sampler (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
output wire       o_full,
output reg  [3:0] ce_ticks,
output reg  [3:0] n_in,
output reg  [3:0] n_out,
output reg  [3:0] sel_trace
);
    // sampling window closes after MAXS samples have been binned
    localparam [3:0] MAXS = 4'd12;

   // run-length coalescing: consecutive samples aimed at one bin are counted
   // here and folded into that bin register with a single add
   localparam [1:0] PMAX = 2'd3;

   reg [1:0] pend;      // samples staged but not yet folded into a bin
   reg [1:0] pend_sel;  // bin the staged samples belong to
  // the bin write port is clock-gated with i_ce: a coalesced run is queued
  // here and lands in its bin on the next enabled beat
  reg [3:0] fq;        // run awaiting write-back (0 => queue empty)
  reg [1:0] fq_sel;    // bin the queued run belongs to
reg [1:0] sel_prev;  // last observed bin selector (diagnostic only)

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
   initial pend     = 2'd0;
   initial pend_sel = 2'd0;
  initial fq     = 4'd0;
  initial fq_sel = 2'd0;
initial ce_ticks = 4'd0;
initial n_in  = 4'd0;
initial n_out = 4'd0;
initial sel_prev  = 2'd0;
initial sel_trace = 4'd0;

    assign o_full = (total == MAXS);

    wire take = i_ce && (total < MAXS);
   wire same  = (i_sel == pend_sel);
   // window already shut: commit whatever is still staged on the next beat
   wire drain = i_ce && !take;
   wire fold  = (pend != 2'd0) && (drain || (take && (!same || pend == PMAX)));
// in/out sample ledger: samples presented minus samples retired is the
// number still sitting in the staging accumulator
wire [3:0] staged   = n_in - n_out;
// one add commits the whole staged run, plus the in-flight sample when it
// coalesces into the same bin
wire [3:0] fold_amt = staged + ((take && same) ? 4'd1 : 4'd0);
// samples leaving staging this beat: those folded into a bin, plus the
// sample dropped on the floor once the window has shut
wire [3:0] retire   = (fold ? fold_amt : 4'd0) + (drain ? 4'd1 : 4'd0);
// the queued run is written back only on an enabled beat
wire wb = i_ce && (fq != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
           pend     <= 2'd0;
           pend_sel <= 2'd0;
           fq       <= 4'd0;
           fq_sel   <= 2'd0;
ce_ticks <= 4'd0;
n_in     <= 4'd0;
n_out    <= 4'd0;
sel_prev  <= 2'd0;
sel_trace <= 4'd0;
       end else begin
          if (wb) begin
              case (fq_sel)
2'd0: bin0 <= bin0 + fq;
2'd1: bin1 <= bin1 + fq;
2'd2: bin2 <= bin2 + fq;
2'd3: bin3 <= bin3 + fq;
               endcase
           end
          if (i_ce) begin
              fq <= fold ? fold_amt : 4'd0;
              if (fold)
                  fq_sel <= pend_sel;
          end
           if (take) begin
               pend_sel <= i_sel;
               pend     <= same ? ((pend == PMAX) ? 2'd0 : pend + 2'd1)
                                : 2'd1;
               total    <= total + 4'd1;
           end else if (drain) begin
               pend <= 2'd0;
           end
if (i_ce && ce_ticks != 4'd15)
    ce_ticks <= ce_ticks + 4'd1;
// ledger is pure accounting: it wraps, it is never held off
n_in  <= n_in  + (i_ce ? 4'd1 : 4'd0);
n_out <= n_out + retire;
sel_prev <= i_sel;
if (i_ce && (i_sel != sel_prev) && sel_trace != 4'd15)
    sel_trace <= sel_trace + 4'd1;
       end
    end

    // P: no single bin's occupancy can ever exceed the sampling-window size,
    // even though the 4-bit bin register could physically hold 15.
    always @(*)
        assert (bin1 <= MAXS);
endmodule

