        if (rst) begin
            pipe    <= {STAGES{1'b0}};
           pipe_b  <= 2'b00;
            cnt     <= 3'd0;
           n_in    <= 3'd0;
           n_out   <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
           ln_stage <= 1'b0;
          ln_tag   <= 1'b0;
          rr       <= 1'b0;
           xpr      <= 1'b0;
        end else if (i_ce) begin
         pipe    <= { pipe[STAGES-2:0], ln_stage && !ln_tag && !xpr_take };
         pipe_b  <= { pipe_b[0],        ln_stage &&  ln_tag && !xpr_take };
        n_in    <= n_in_nxt;
        n_out   <= n_out_nxt;
        cnt     <= n_in_nxt - n_out_nxt;
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
           ln_stage <= i_launch && armed;
          ln_tag   <= rr;
          rr       <= rr ^ (i_launch && armed);
          xpr     <= xpr_take;
