: (credit - (acc ? 3'd1 : 3'd0) + (lend ? 3'd1 : 3'd0));
rtn    <= drained ? 3'd0
                  : (rtn - (fold ? 3'd1 : 3'd0) + (wb ? 3'd1 : 3'd0));
resv   <= drained ? 3'd0
                 : (resv + (fold ? 3'd1 : 3'd0) - (lend ? 3'd1 : 3'd0));
n_iss  <= n_iss + (acc ? 3'd1 : 3'd0);
n_ret  <= n_ret + (wb  ? 3'd1 : 3'd0);
if (acc)
                armed <= 1'b1;
end
if (i_ce)
beat <= !beat && wb;
