module pwm_precedence (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [3:0] duty_in,
    output wire       o_pwm,
   output wire       o_period_start,
   output reg  [3:0] beat_ctr
);
    // 12-cycle PWM period: counter runs 0..11 and reloads.
    localparam [3:0] PERIOD_M1 = 4'd11;

    reg [3:0] cnt;       // period counter
    reg [3:0] duty_act;  // active duty, latched at period start
    reg [3:0] duty_pend; // pending (requested) duty
    reg [3:0] hi_left;   // shadow: high-cycle budget recorded at last period start
    reg [3:0] duty_stg;  // prefetched duty feeding the compare path
   reg [3:0] req_val;   // duty value captured from the request bus
   reg       req_vld;   // captured request still waiting to be committed
  reg [3:0] n_stage;   // running count of duty_pend -> duty_stg stage loads
  reg [3:0] n_commit;  // running count of duty_stg -> duty_act reloads
 // two duty slots are played on alternating periods so the average duty
 // lands between them (half-LSB dither); the compare path, the staging
 // register and the request capture are shared between the two slots
 reg [3:0] duty_pend_b; // pending duty for the B slot
 reg       ph;          // slot the period now running was loaded from
 reg       wr_sel;      // next accepted request programs the B slot
reg [3:0] beat_ctr_unused_dummy_placeholder_removed = 4'd0; // (unused)

    initial cnt       = 4'd0;
    initial duty_act  = 4'd0;
    initial duty_pend = 4'd0;
    initial hi_left   = 4'd0;
    initial duty_stg  = 4'd0;
   initial req_val   = 4'd0;
   initial req_vld   = 1'b0;
  initial n_stage   = 4'd0;
  initial n_commit  = 4'd0;
 initial duty_pend_b = 4'd0;
 initial ph          = 1'b0;
 initial wr_sel      = 1'b0;
initial beat_ctr    = 4'd0;

    wire wrap = (cnt == PERIOD_M1);
    wire prefetch = (cnt == PERIOD_M1 - 4'd1);
   wire prefetch2 = (cnt == PERIOD_M1 - 4'd2);
   // a captured request only reaches duty_pend one cycle after it is
   // accepted, so the accept window has to close three cycles before the
   // boundary for the duty pipeline to be stable across the reload
   wire duty_hold = prefetch2 || prefetch || wrap;

    // seeded construct: output high exactly while the counter is below the duty
    assign o_pwm          = (cnt < duty_act);
    assign o_period_start = (cnt == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            // prefetch one cycle ahead of the boundary so the cnt<duty
            // compare gets a full cycle of setup on the new duty value
           if (prefetch) begin
             // the period after this one runs the other slot
             duty_stg <= ph ? duty_pend : duty_pend_b;
               n_stage  <= n_stage + 4'd1;
           end
            if (wrap) begin
                // new period: both the active duty and the high budget are
                // (re)loaded from the pending duty requested earlier
                cnt      <= 4'd0;
               // the staged value is consumed exactly once: the reload only
               // fires when the ledger still shows an un-consumed stage load,
               // otherwise duty_stg already sits in duty_act
               if (n_stage != n_commit) begin
                   duty_act <= duty_stg;
                   n_commit <= n_commit + 4'd1;
               end
              hi_left  <= ph ? duty_pend : duty_pend_b;
              ph       <= ~ph;
            end else begin
                cnt <= cnt + 4'd1;
                if (hi_left != 4'd0)
                    hi_left <= hi_left - 4'd1;
            end
           // request bus is registered: capture on the accepted cycle and
           // commit into the pending duty on the following cycle
           if (load && !duty_hold) begin
               req_val <= duty_in;
               req_vld <= 1'b1;
           end else begin
               req_vld <= 1'b0;
           end
          // consecutive accepted writes program the A slot then the B slot
          if (req_vld) begin
              if (wr_sel) duty_pend_b <= req_val;
              else        duty_pend   <= req_val;
              wr_sel <= ~wr_sel;
          end
         // diagnostic: count elapsed PWM periods; observation only
         if (cnt == 4'd0)
             beat_ctr <= beat_ctr + 4'd1;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 0;
    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: if the output was driven high last cycle, then a nonzero
    // high-cycle budget (recorded at the earlier period start) must still have
    // been available at that time.
    always @(posedge clk)
        if (pv && $past(o_pwm))
            assert ($past(hi_left) != 4'd0);
endmodule

