// Debug-probe challenge sequencer: a maximal-length LFSR supplies one tick per
// chain step (arm -> start -> finish). The LFSR is seeded non-zero and can never
// enter the all-zeros lockup state, so every FSM advance is accompanied by a
// genuine change of the challenge shift register.
module probe_chain_seq (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       arm,
    input  wire       start,
    input  wire       fin,
    output reg  [1:0] stage,
    output reg        pre_done,
    output reg  [3:0] chal
);
    // stage encoding: 0 = IDLE, 1 = ARMED, 2 = RUNNING, 3 = DONE
    reg [3:0] lfsr;
    reg       pv;
    // channel B: second probe chain sharing the one challenge generator
    reg [1:0] stage_b;
    reg       own;      // 0 = chain A holds the generator, 1 = chain B
    reg       ld;       // generator context restore in flight (owner stalls)
    reg       chal_ok;  // chal holds a valid generator word
  // the challenge register is written over a 2-bit-wide debug bus, so a new
  // word lands in two beats: the low half is driven immediately and the high
  // half is staged here until the following enabled cycle
  reg [1:0] chal_hi;
  reg       chal_ph;  // high half still owed to the challenge register
   // per-chain generator context: a chain preempted by the arbiter resumes
   // its own point in the challenge stream when it gets the generator back
   reg [3:0] ctx_a;
   reg [3:0] ctx_b;
  // preemption save buffer: the context file is written over the same 2-bit
  // debug port as the challenge register, so a parked resume word lands low
  // half first and high half on the next free beat
  reg [1:0] ctx_hi;
  reg       ctx_ph;   // high half of a parked context still owed
  reg       ctx_sel;  // 0 = save targets ctx_a, 1 = targets ctx_b
   reg [2:0] tmr;      // round-robin time slice for the shared generator

    initial lfsr     = 4'b0001;
    initial chal     = 4'b0000;
    initial stage    = 2'd0;
    initial pre_done = 1'b1;   // before-scope: high until the first DONE ever
    initial pv       = 1'b0;
    initial stage_b  = 2'd0;
    initial own      = 1'b0;
    initial ld       = 1'b0;
    initial chal_ok  = 1'b0;
  initial chal_hi  = 2'b00;
  initial chal_ph  = 1'b0;
   initial ctx_a    = 4'b0000;
   initial ctx_b    = 4'b0000;
  initial ctx_hi   = 2'b00;
  initial ctx_ph   = 1'b0;
  initial ctx_sel  = 1'b0;
   initial tmr      = 3'd7;

    // x^4 + x^3 + 1 : period 15 over the non-zero states
    wire       fb        = lfsr[3] ^ lfsr[2];
    wire [3:0] lfsr_next = {lfsr[2:0], fb};

   // A chain that has left IDLE owns a parked generator word and resumes from
   // it; a chain that is IDLE starts cold from the last challenge issued on
   // the shared bus, or from the cold seed if none has been issued yet.
   wire       in_a      = (stage   != 2'd0);
   wire       in_b      = (stage_b != 2'd0);
   wire [3:0] cold      = chal_ok ? chal : 4'b0001;
   wire [3:0] lfsr_rest = own ? (in_b ? ctx_b : cold)
                              : (in_a ? ctx_a : cold);

    // the current owner releases the generator once its chain reaches DONE
    wire a_done = (stage   == 2'd3);
    wire b_done = (stage_b == 2'd3);
   // ... or when its arbitration time slice expires, so a chain that stalls
   // mid-run cannot hold the shared generator forever
   wire slice_up = (tmr == 3'd0);
  // a preemption cannot start while the previous context save is still
  // draining, or the parked word would be half of one chain and half of
  // another
  wire yield    = !ld && !ctx_ph && (slice_up || (own ? b_done : a_done));

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= ld ? lfsr_rest : lfsr_next;
           if (yield) begin
               own <= ~own;
              // park the outgoing chain's stream: low half straight away,
              // high half staged for the save buffer
              if (own) ctx_b[1:0] <= lfsr_next[1:0];
              else     ctx_a[1:0] <= lfsr_next[1:0];
              ctx_hi  <= lfsr_next[3:2];
              ctx_sel <= own;
              ctx_ph  <= 1'b1;
               tmr <= 3'd7;
           end else if (!ld) begin
               tmr <= tmr - 3'd1;
           end
            ld <= yield;
          // second beat: the staged high half lands and the challenge word
          // becomes valid for chains that start cold from the shared bus
          if (chal_ph) begin
              chal[3:2] <= chal_hi;
              chal_ok   <= 1'b1;
              chal_ph   <= 1'b0;
          end
         // the save buffer drains on the first beat the debug port is not
         // carrying a challenge half
         if (ctx_ph && !chal_ph) begin
             if (ctx_sel) ctx_b[3:2] <= ctx_hi;
             else         ctx_a[3:2] <= ctx_hi;
             ctx_ph <= 1'b0;
         end
            if (!ld) begin
            if (!own) begin
            case (stage)
               2'd0: if (arm && !chal_ph) begin
                          stage <= 2'd1;
                         chal[1:0] <= lfsr[1:0];   // first beat on the bus
                         chal_hi   <= lfsr[3:2];    // high half next cycle
                         chal_ph   <= 1'b1;
                         chal_ok   <= 1'b0;         // incomplete until commit
                     ctx_a <= lfsr_next;  // resume point for this chain
                      end
                2'd1: if (start) stage <= 2'd2;
                2'd2: if (fin) begin
                          stage    <= 2'd3;   // finish: clears the before-scope
                          pre_done <= 1'b0;
                      end
                default: stage <= 2'd0;
            endcase
            end else begin
                case (stage_b)
                   2'd0: if (arm && !chal_ph) begin
                              stage_b <= 2'd1;
                             chal[1:0] <= lfsr[1:0];
                             chal_hi   <= lfsr[3:2];
                             chal_ph   <= 1'b1;
                             chal_ok   <= 1'b0;
                             ctx_b <= lfsr_next;
                          end
                    2'd1: if (start) stage_b <= 2'd2;
                    2'd2: if (fin)   stage_b <= 2'd3;
                    default: stage_b <= 2'd0;
                endcase
            end
            end
        end
    end

    // P: before the first finish has ever been observed, the chain FSM cannot
    //    move unless the challenge shift register moved with it.
    always @(posedge clk)
        if (pv && pre_done && $stable(lfsr))
            assert ($stable(stage));

   // Q: a chain that has been armed has a live challenge on the bus, so once
   //    chain A is running the challenge register reads back non-zero -- the
   //    only exception is the single beat where the high half is still owed.
   always @(posedge clk)
       if (pv && stage == 2'd2)
           assert (chal != 4'd0 || chal_ph);
endmodule

