module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
output reg  [1:0] stage,
output reg  [3:0] act_cnt
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;
   // peer chain B: shares the start unit with chain A
   // arm(line2) -> start(line3) -> finish(line1)
   reg [1:0] stage_b;
   // shared start unit is primed and not yet consumed
   reg       start_tok;
  // peer chain C: second port on the same shared start unit
  // arm(line1) -> start(line2) -> finish(line0)
  reg [1:0] stage_c;
  // port C's primed-and-unconsumed flag
  reg       start_tok_c;
 // shared-start-unit ledger: one entry logged per acquire, one per release
 reg [3:0] tok_acq;
 reg [3:0] tok_rel;
  // posted stage-update pipe: a chain A stage advance is handed to the
  // writeback pipe and only lands on the stage register four cycles later.
  // 2'd0 in a slot means "nothing posted here".
  reg [1:0] upd_p0;
  reg [1:0] upd_p1;
  reg [1:0] upd_p2;
  reg [1:0] upd_p3;
// distractor: previous request vector, used only for the activity counter
reg [3:0] req_prev;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       start_tok  = 1'b0;
      stage_c     = 2'd0;
      start_tok_c = 1'b0;
     tok_acq    = 4'd0;
     tok_rel    = 4'd0;
      upd_p0     = 2'd0;
      upd_p1     = 2'd0;
      upd_p2     = 2'd0;
      upd_p3     = 2'd0;
req_prev   = 4'b0000;
act_cnt    = 4'd0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);
  // only one stage update may be outstanding in the pipe
  wire upd_busy = (upd_p0 | upd_p1 | upd_p2 | upd_p3) != 2'd0;
 // ledger view of the shared start unit: a nonzero balance means some
 // acquire has not been returned yet, so the unit is still primed
 wire [3:0] tok_bal  = tok_acq - tok_rel;
 wire       tok_out  = (tok_bal != 4'd0);
 // acquire side: chain B primes the unit on its START step
 wire       tok_grab = fire && (stage_b == 2'd1) && gnt_c[3];
 // return side: B consumes it, or chain A tears it down on abort/retire.
 // a teardown that finds no held unit is not a return, so it is not logged.
 wire       tok_drop = fire && !tok_grab && start_tok &&
                       (((stage_b == 2'd2) && gnt_c[1]) ||
                        (stage == 2'd3) ||
                        (((stage == 2'd1) || (stage == 2'd2)) && gnt_c[3]));
// port C acquires on its START step and returns it on its FINISH step;
// a chain A teardown tears the peer port down as well
wire       tok_grab_c = fire && (stage_c == 2'd1) && gnt_c[2];
wire       tok_drop_c = fire && !tok_grab_c && start_tok_c &&
                       (((stage_c == 2'd2) && gnt_c[0]) ||
                        (stage == 2'd3) ||
                        (((stage == 2'd1) || (stage == 2'd2)) && gnt_c[3]));

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
// shared-start-unit ledger, free running, wraps at 4 bits;
// both ports log through the same pair of counters
tok_acq <= tok_acq + {3'd0, tok_grab} + {3'd0, tok_grab_c};
tok_rel <= tok_rel + {3'd0, tok_drop} + {3'd0, tok_drop_c};
      if (i_ce) begin
          // last slot retires onto the stage register, then the pipe shifts
          if (upd_p3 != 2'd0)
              stage <= upd_p3;
          upd_p3 <= upd_p2;
          upd_p2 <= upd_p1;
          upd_p1 <= upd_p0;
          upd_p0 <= 2'd0;
      end
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                   if (gnt_c[0] && !upd_busy) begin
                       upd_p0   <= 2'd1;   // post ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                   if (gnt_c[1] && !upd_busy) begin
                       upd_p0     <= 2'd2; // post START step
                        seen_start <= 1'b1;
end else if (tok_out && gnt_c[2] && !upd_busy) begin
                      upd_p0     <= 2'd3; // start unit already primed: skip START
                   end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
start_tok_c <= 1'b0; // tear down the peer port as well
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                2'd2: begin
                   if (gnt_c[2] && !upd_busy) begin
                       upd_p0 <= 2'd3;     // post FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                       start_tok  <= 1'b0; // release shared start unit
start_tok_c <= 1'b0; // tear down the peer port as well
                      upd_p0     <= 2'd0; // abort flushes the posted update
                      upd_p1     <= 2'd0;
                      upd_p2     <= 2'd0;
                      upd_p3     <= 2'd0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                   start_tok  <= 1'b0;     // release shared start unit
start_tok_c <= 1'b0;     // tear down the peer port as well
                  upd_p0     <= 2'd0;     // nothing left to post
                  upd_p1     <= 2'd0;
                  upd_p2     <= 2'd0;
                  upd_p3     <= 2'd0;
                end
            endcase
           // peer chain B drives the same start unit from the high lines
           case (stage_b)
               2'd0: if (gnt_c[2]) stage_b <= 2'd1;   // ARM step (B)
               2'd1: if (gnt_c[3]) begin
                         stage_b    <= 2'd2;          // START step (B)
                         seen_start <= 1'b1;          // shared unit has run
                         start_tok  <= 1'b1;          // and stays primed
                     end
               2'd2: if (gnt_c[1]) begin
                         stage_b   <= 2'd3;           // FINISH step (B)
                         start_tok <= 1'b0;           // B consumes the unit
                     end
               default: stage_b <= 2'd0;              // retire B
           endcase
          // peer chain C drives the second port of the same start unit
          case (stage_c)
              2'd0: if (gnt_c[1]) stage_c <= 2'd1;   // ARM step (C)
              2'd1: if (gnt_c[2]) begin
                        stage_c     <= 2'd2;         // START step (C)
                        seen_start  <= 1'b1;         // shared unit has run
                        start_tok_c <= 1'b1;         // and stays primed
                    end
              2'd2: if (gnt_c[0]) begin
                        stage_c     <= 2'd3;         // FINISH step (C)
                        start_tok_c <= 1'b0;         // C consumes the unit
                    end
              default: stage_c <= 2'd0;              // retire C
          endcase
        end
// distractor activity counter: counts request-vector changes while enabled
if (i_ce) begin
req_prev <= req;
if (req != req_prev)
act_cnt <= act_cnt + 4'd1;
end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

