module chess_clock_seq_alarm (
    input  wire clk,
    input  wire i_ce,      // clock tick enable; low freezes the whole mechanism
    input  wire sym,       // observed press: 1 = white side, 0 = black side
    output reg  alarm
);
    // match-progress register for the fixed press pattern 1,0,1,1
    // (white, black, white, white) -- the blitz alarm trigger
    reg [2:0] prog;
    // shadow register: latches that the half-way progress (2 symbols) occurred
    reg       seen_half;
    // "before R" scope register: high until the alarm pattern first completes
    reg       before_alarm;
   // commit stage: the decoder's next-progress value waits one tick here
   // before it is retired into the matcher, keeping the decode path short
   reg [2:0] stg;
   reg       stg_v;       // a staged progress value is pending commit
  // black-turn tally: how many times the matcher has passed the half-way
  // point since power-up. The blitz time control also ends the game once
  // this tally reaches its limit of seven, so it feeds the alarm too.
  reg [2:0] hcnt;
 // black-side peer matcher for the press pattern 0,1,0,0 (black, white,
 // black, black) -- the other side's blitz trigger. It shares the commit
 // stage and the tally's single increment port with the white-side matcher.
 reg [2:0] prog2;
 reg [2:0] stg2;
 // the tally adder accepts one increment per tick; a half-way pass that
 // loses the arbitration is owed and is retired in the commit phase
 reg       hpend;
 reg       harb;   // round-robin pointer for the tally increment port
// black-side half-way shadow, the peer of seen_half.  Both shadows are
// written through one shared notice slot: a matcher that crosses its
// half-way point posts a notice here and the slot retires it into the
// selected shadow on the following tick.
reg       seen_half2;
reg       nq_v;   // a half-way notice is waiting in the slot
reg       nq_s;   // 0 = white shadow, 1 = black shadow
// four-deep retire pipeline: a committed progress pair walks cm1..cm4
// (white) / cn1..cn4 (black) one hop per tick before it lands in the
// matchers, so the retire bus is registered at every hop.  cv1..cv4 mark
// which hop currently carries the press in flight.
reg [2:0] cm1, cm2, cm3, cm4;
reg [2:0] cn1, cn2, cn3, cn4;
reg       cv1, cv2, cv3, cv4;

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;
   initial stg          = 3'd0;
   initial stg_v        = 1'b0;
  initial hcnt         = 3'd0;
 initial prog2        = 3'd0;
 initial stg2         = 3'd0;
 initial hpend        = 1'b0;
 initial harb         = 1'b0;
initial seen_half2   = 1'b0;
initial nq_v         = 1'b0;
initial nq_s         = 1'b0;
initial cm1          = 3'd0;
initial cm2          = 3'd0;
initial cm3          = 3'd0;
initial cm4          = 3'd0;
initial cn1          = 3'd0;
initial cn2          = 3'd0;
initial cn3          = 3'd0;
initial cn4          = 3'd0;
initial cv1          = 1'b0;
initial cv2          = 1'b0;
initial cv3          = 1'b0;
initial cv4          = 1'b0;

    reg [2:0] nxt;
   reg [2:0] nxt2;
  // a new press may only be taken once the retire pipeline has drained
  wire idle = !stg_v && !cv1 && !cv2 && !cv3 && !cv4;
   // a press is only consumed in the decode phase
  wire match = (prog == 3'd3) && sym && idle;
 wire match2 = (prog2 == 3'd3) && !sym && idle;
  // tally requests: either matcher asks when it passes its half-way point
  wire req1 = (nxt  == 3'd2);
  wire req2 = (nxt2 == 3'd2);
  wire gnt1 = req1 && (!req2 || !harb);
  wire gnt2 = req2 && (!req1 ||  harb);

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

   always @(*) begin
       case (prog2)
           3'd0: nxt2 = sym ? 3'd0 : 3'd1;
           3'd1: nxt2 = sym ? 3'd2 : 3'd1;
           3'd2: nxt2 = sym ? 3'd0 : 3'd3;
           3'd3: nxt2 = sym ? 3'd2 : 3'd0;  // overlap: "01" survives
           default: nxt2 = 3'd0;
       endcase
   end

    always @(posedge clk) begin
        if (i_ce) begin
          // the retire pipeline advances one hop on every tick
          cm1 <= stg;   cn1 <= stg2;   cv1 <= stg_v;
          cm2 <= cm1;   cn2 <= cn1;    cv2 <= cv1;
          cm3 <= cm2;   cn3 <= cn2;    cv3 <= cv2;
          cm4 <= cm3;   cn4 <= cn3;    cv4 <= cv3;
          if (cv4) begin
              // retire phase: the value that has walked the whole pipeline
              // lands in the two matchers
              prog      <= cm4;
              prog2     <= cn4;
              if (cm4 == 3'd0)
                  seen_half <= 1'b0;   // white matcher restarted
if (cn4 == 3'd0)
    seen_half2 <= 1'b0;  // black matcher restarted
          end
          if (idle) begin
               // decode phase: consume the press, stage the new progress
               stg       <= nxt;
              stg2      <= nxt2;
               stg_v     <= 1'b1;
// post the half-way crossing into the shared shadow notice slot
nq_v      <= req1 | req2;
nq_s      <= !req1;
