             alarm     <= hpend && (hcnt == 3'd6);
           end
          else begin
              // the retire pipeline is still draining: no new alarm source
              alarm     <= 1'b0;
          end
// shadow retire: the notice posted last tick lands in its shadow
if (nq_v) begin
    nq_v <= 1'b0;
    if (!nq_s)
        seen_half  <= 1'b1;
    else
        seen_half2 <= 1'b1;
    // warning chime: this crossing puts both sides past half-way
