        o_zero  = 1'b1;
        o_carry = 1'b0;
       stg_v   = 1'b0;
       stg_d   = 9'd0;
      skid_v  = 1'b0;
      skid_d  = 9'd0;
      n_push  = 4'd0;
      n_pop   = 4'd0;
