// PWM channel for a wire-logic accelerator block.
// Period counter walks 0..PER-1, duty is double buffered at the period edge,
// and high_cnt accumulates the number of high cycles elapsed in the period.
module pwm_channel (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire       i_load,
    input  wire [3:0] i_duty,
    output wire       pwm_out,
output reg        armed,
output reg [3:0]  dbg_load_cnt
);
    localparam [3:0] PER = 4'd12;
   localparam [3:0] HALF = 4'd6;   // the period is walked as two half windows

   reg [3:0] cnt;       // sub-counter inside the current half, 0 .. HALF-1
   reg       half;      // 0 = first half of the period, 1 = second half
    reg [3:0] duty;      // active duty, 0 .. PER
    reg [3:0] high_cnt;  // high cycles elapsed so far this period
   reg       pwm_q;     // registered output stage, resolved one cycle ahead
  reg [3:0] duty_b;    // nested window duty, kept inside the main window
  reg       pwm_b_q;   // registered output stage of the nested window
  reg       sel;       // owner of the shared duty load port: 0 = main, 1 = nested
reg [1:0] load_hist;  // recent i_load request history (debug only)

    initial begin
        cnt      = 4'd0;
       half     = 1'b0;
        duty     = 4'd0;
        high_cnt = 4'd0;
        armed    = 1'b0;
       pwm_q    = 1'b0;
       duty_b   = 4'd0;
       pwm_b_q  = 1'b0;
       sel      = 1'b0;
load_hist    = 2'd0;
dbg_load_cnt = 4'd0;
    end

    // the construct: output high exactly while the counter is below the duty
  // both windows share one open-drain pad, so the pin is the wire-OR of the
  // two output stages
  assign pwm_out = pwm_q | pwm_b_q;

    wire [3:0] duty_clamped = (i_duty > PER) ? PER : i_duty;
   wire       at_half      = (cnt == HALF - 4'd1);
   wire       at_edge      = half && at_half;
   // full period phase reassembled from the two halves, 0 .. PER-1
   wire [3:0] phase        = half ? (cnt + HALF) : cnt;

   // Next-cycle counter and duty. The output register is loaded from these so
   // the pin keeps the same alignment the combinational comparator had, while
   // the compare itself is off the critical path.
  wire [3:0] cnt_nxt   = at_half ? 4'd0 : cnt + 4'd1;
  wire       half_nxt  = at_half ? ~half : half;
  wire [3:0] phase_nxt = at_edge ? 4'd0 : phase + 4'd1;
 wire [3:0] duty_nxt = (at_edge && i_load && !sel) ? duty_clamped : duty;
 // The nested window is clamped into the main window when it is loaded, and
 // retrimmed whenever the main channel takes a smaller duty.
 wire [3:0] duty_b_req  = (i_duty > duty) ? duty : i_duty;
 wire [3:0] duty_b_trim = (duty_b > duty_clamped) ? duty_clamped : duty_b;
 wire [3:0] duty_b_nxt  = (at_edge && i_load) ? (sel ? duty_b_req : duty_b_trim)
                                              : duty_b;

    always @(posedge clk) begin
        if (rst) begin
            cnt      <= 4'd0;
           half     <= 1'b0;
            duty     <= 4'd0;
            high_cnt <= 4'd0;
            armed    <= 1'b0;
           pwm_q    <= 1'b0;
           duty_b   <= 4'd0;
           pwm_b_q  <= 1'b0;
           sel      <= 1'b0;
load_hist    <= 2'd0;
dbg_load_cnt <= 4'd0;
        end else if (i_ce) begin
          pwm_q <= (phase_nxt < duty_nxt);
         pwm_b_q <= (phase_nxt < duty_b_nxt);
load_hist <= {load_hist[0], i_load};
if (i_load && !load_hist[0]) begin
    dbg_load_cnt <= dbg_load_cnt + 4'd1;
end
            if (at_edge) begin
                // period rolls over: new duty takes effect, accumulator clears
                cnt      <= 4'd0;
               half     <= 1'b0;
                high_cnt <= 4'd0;
                armed    <= 1'b1;            // sticky, never cleared
               sel <= ~sel;                 // round-robin the shared load port
               if (i_load) begin
                   if (sel) begin
                       duty_b <= duty_b_req;
                   end else begin
                       duty   <= duty_clamped;
                       duty_b <= duty_b_trim;
                   end
               end
            end else begin
               cnt      <= cnt_nxt;
               half     <= half_nxt;
                high_cnt <= high_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // Property (universality, after the first completed period):
    // the accumulated high time never exceeds the duty, and the live output
    // agrees with the accumulator's headroom.
    always @(posedge clk)
        if (armed)
            assert (high_cnt <= duty);

    always @(posedge clk)
        if (armed)
            assert (pwm_out == (high_cnt < duty));
