module arb_lock_pending (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire [3:0] req,     // new requests, latched into pend
    input  wire       rel,     // current owner releases the lock
    output wire [3:0] grant,
output wire [2:0] occupancy,
output wire [3:0] evt_count
);
    // pending request bitmap and its redundant occupancy counter
    reg [3:0] pend  = 4'b0000;
    reg [2:0] pcnt  = 3'd0;
reg [2:0] lcnt  = 3'd0;   // bank A entries admitted on the last credit
reg [3:0] late  = 4'b0000; // arrival class of each pending lane
   reg [2:0] bcnt  = 3'd0;   // bank B (indices 2,3) occupancy
    // fixed-priority arbiter with a lock bit freezing the winner
    reg       lock  = 1'b0;
    reg [1:0] owner = 2'd0;
    reg       pv    = 1'b0;   // past-valid

   // service ledger: every admission and every retirement is logged,
   // both counters free-run and wrap at four bits
   reg [3:0] n_in  = 4'd0;
   reg [3:0] n_out = 4'd0;
// activity monitor: counts completed release handshakes (observation only)
reg [3:0] rel_cnt = 4'd0;

    // fixed priority: lowest index wins
// within bank A a fresh arrival outranks a late one; index breaks ties
wire [1:0] pick_a = (pend[0] && !late[0]) ? 2'd0 :
                    (pend[1] && !late[1]) ? 2'd1 :
                    pend[0]               ? 2'd0 : 2'd1;
wire [1:0] pick_b = pend[2] ? 2'd2 : 2'd3;
// drain the fuller bank first; ties break toward bank A
// work still outstanding per the ledger, and the bank A share of it
wire [3:0] bal     = n_in - n_out;
wire [2:0] a_bal   = bal[2:0] - bcnt;
wire       serve_b = (bcnt > a_bal);
wire [1:0] pick    = serve_b ? pick_b : pick_a;
    wire       any  = |pend;

    // service completion: the locked owner releases, its pending bit retires
    wire       do_clr   = ce && lock && rel;
    wire [3:0] clr_mask = do_clr ? (4'b0001 << owner) : 4'b0000;
    // only genuinely new requests are inserted
// credit limit: admission stops once three entries are outstanding
wire       adm      = (bal < 4'd3);
wire [3:0] set_mask = (ce && adm) ? (req & ~pend & ~clr_mask) : 4'b0000;
// the last credit is handed to late arrivals, which are booked apart
wire       mark_late = (bal >= 4'd2);
wire [3:0] late_set  = mark_late ? set_mask : 4'b0000;
wire [3:0] late_clr  = (set_mask & ~late_set) | clr_mask;
wire [3:0] fresh_set = set_mask & ~late_set;
wire [2:0] nset_a   = fresh_set[0] + fresh_set[1];
wire [2:0] nset_l   = late_set[0] + late_set[1];
wire [2:0] nset_b   = set_mask[2] + set_mask[3];
wire       dec_a    = do_clr && !owner[1] && !late[owner];
wire       dec_l    = do_clr && !owner[1] &&  late[owner];
wire       dec_b    = do_clr &&  owner[1];

    assign grant     = lock ? (4'b0001 << owner) : 4'b0000;
assign occupancy = pcnt + lcnt + bcnt;
assign evt_count = rel_cnt;

always @(posedge clk) begin
    if (ce && rel)
        rel_cnt <= rel_cnt + 4'd1;
end

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            pend <= (pend | set_mask) & ~clr_mask;
pcnt <= pcnt + nset_a - (dec_a ? 3'd1 : 3'd0);
lcnt <= lcnt + nset_l - (dec_l ? 3'd1 : 3'd0);
late <= (late | late_set) & ~late_clr;
bcnt <= bcnt + nset_b - (dec_b ? 3'd1 : 3'd0);
n_in  <= n_in  + {1'b0, nset_a} + {1'b0, nset_l} + {1'b0, nset_b};
n_out <= n_out + {3'd0, dec_a} + {3'd0, dec_l} + {3'd0, dec_b};
            if (lock) begin
                if (rel)
                    lock <= 1'b0;      // frozen winner until it releases
            end else if (any) begin
                lock  <= 1'b1;
                owner <= pick;
            end
        end
    end

    // P: if the pending bitmap did not change, the occupancy must not have
    // changed either, and the occupancy stays within its real bound of 4.
    always @(posedge clk)
        if (pv && $stable(pend))
            assert ($stable(pcnt) && (pcnt <= 3'd4));
endmodule

