module gray_quantum_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // scheduler quantum tick enable
    output wire [3:0] o_gray,
    output wire [2:0] o_ones
);
    // Ten quantum slots (0..9). The binary shadow does the arithmetic,
    // the gray register is what leaves the clock domain. Terminal count is
    // detected on the gray word, as the CDC-facing logic sees it.
    localparam [3:0] GRAY_LAST = 4'b1101; // gray code of 4'd9

    reg [3:0] bin  = 4'd0;
    reg [3:0] gray = 4'b0000;

   // Lane B is the second scheduler quantum lane. To save area the two
   // lanes time-share one binary shadow and one increment/encode
   // datapath: the owner named by `turn` uses `bin`, the parked lane's
   // shadow waits in `bin_hold`, and the pair swaps on every tick.
   reg [3:0] gray_b   = 4'b0000;
   reg [3:0] bin_hold = 4'd0;
   reg       turn     = 1'b0;   // 0: lane A owns the shared shadow

  // Lane C is the third quantum lane (background dispatch class). It
  // joins the same time-share: the shadow of the lane two slots ahead of
  // the owner parks in `bin_hold2`, and `grp` widens the ownership
  // pointer so the trio rotates A -> B -> C -> A, one hand-off per tick.
  reg [3:0] gray_c    = 4'b0000;
  reg [3:0] bin_hold2 = 4'd0;
 reg       grp       = 1'b0;   // {turn,grp,ext}: 000=A, 100=B, 010=C, 001=D

 // Lane D is the realtime dispatch class and the last member of the
 // time-share. Its shadow parks one stage deeper, in `bin_hold3`, and
 // `ext` extends the ownership pointer so the hand-off rotates
 // A -> B -> C -> D -> A, one lane per tick.
 reg [3:0] gray_d    = 4'b0000;
 reg [3:0] bin_hold3 = 4'd0;
 reg       ext       = 1'b0;   // 1: lane D owns the shared shadow


 wire [3:0] gray_sel = ext ? gray_d
                           : (turn ? gray_b : (grp ? gray_c : gray));

   wire       wrap    = (gray_sel == GRAY_LAST);
    wire [3:0] bin_nxt = wrap ? 4'd0 : (bin + 4'd1);

    // occupancy of the gray word: how many lanes are asserted this slot
    wire [2:0] ones = {2'b00, gray[0]} + {2'b00, gray[1]} +
                      {2'b00, gray[2]} + {2'b00, gray[3]};
    wire       occ_hi = (ones >= 3'd3);

    assign o_gray = gray;
    assign o_ones = ones;

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'd0;
            gray <= 4'b0000;
           gray_b   <= 4'b0000;
           bin_hold <= 4'd0;
           turn     <= 1'b0;
          gray_c    <= 4'b0000;
          bin_hold2 <= 4'd0;
          grp       <= 1'b0;
         gray_d    <= 4'b0000;
         bin_hold3 <= 4'd0;
         ext       <= 1'b0;
        end else if (i_ce) begin
          // the lane owning the datapath advances its gray word, then the
          // shared shadow is handed to the next lane in the rotation
         if (ext)       gray_d <= bin_nxt ^ (bin_nxt >> 1);
         else if (turn) gray_b <= bin_nxt ^ (bin_nxt >> 1);
          else if (grp) gray_c <= bin_nxt ^ (bin_nxt >> 1);
          else          gray   <= bin_nxt ^ (bin_nxt >> 1);
          bin       <= bin_hold;
          bin_hold  <= bin_hold2;
         bin_hold2 <= bin_hold3;
         bin_hold3 <= bin_nxt;
         turn      <= !turn && !grp && !ext;
          grp       <= turn;
         ext       <= !turn && grp;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);

   // Lane coherence: the swap is only half done while lane B holds the
   // shared shadow. Once ownership is back with lane A both lanes have
   // been advanced to the same quantum slot, so the two gray words the
   // CDC side can sample are identical.
   always @(posedge clk)
       if (pv) assert (turn || (gray == gray_b));
endmodule

