// Triple-modular-redundant power-rail sequencer step counter.
// Three shadow copies of the sequencer step code are advanced independently;
// the exported step code is the bitwise majority vote of the three copies.
// prev_voted is a precedence shadow: it records the voted code as it was at
// the previous advance, so the present code must be the successor of the code
// that was observed earlier.
module tmr_rail_sequencer (
    input  wire       clk,
    input  wire       ce,        // advance / load enable; low => design idles
    input  wire       load,      // reload the sequencer with an external code
    input  wire [2:0] code_in,
    input  wire       q_start,   // opens the monitoring window
    input  wire       r_stop,    // closes the monitoring window
    output wire [2:0] voted
);

    // three shadow registers of the TMR voter
    reg [2:0] shadow_a = 3'd1;
    reg [2:0] shadow_b = 3'd1;
    reg [2:0] shadow_c = 3'd1;
    // Ring bounds of the rail ramp. The last load fixes the origin:
    // base_code is the first code of the ring and top_code the code after
    // which the sequencer wraps back to the origin. at_top is the registered
    // terminal-count flag, kept out of the voter's compare path.
    reg [2:0] base_code = 3'd1;
    reg [2:0] top_code  = 3'd0;
    reg       at_top    = 1'b0;
   // Wrap reseed value: the predecessor of the ring origin, captured when the
   // origin is loaded so that the wrap path carries no decrementer.
   reg [2:0] seed_code = 3'd0;
   // Load phase: alternate loads program the origin, then the wrap point.
   reg       cfg_sel   = 1'b0;
  // Ramp length: index of the last step of the ring, counted from the origin.
  // A fresh origin load opens the ring to its full length; a wrap-point load
  // narrows it. pos is the index of the code held in the precedence shadow,
  // so that path can time the wrap without carrying a code comparator.
  reg [2:0] ring_len = 3'd7;
  reg [2:0] pos      = 3'd0;

// Precedence shadow, split for radiation tolerance: the low two bits of the
// recorded code ripple in prev_lo, while its top bit is kept as a dual-rail
// pair whose advance is a swap of the two rails.
reg [1:0] prev_lo   = 2'd0;
reg       prev_hi_t = 1'b0;
reg       prev_hi_f = 1'b1;

    // window register: set by q_start, cleared by r_stop, reopenable
    reg       win = 1'b0;

    // bitwise majority vote
    assign voted = (shadow_a & shadow_b) | (shadow_a & shadow_c) |
                   (shadow_b & shadow_c);

// recomposed precedence code
wire [2:0] prev_voted = {prev_hi_t, prev_lo};
    // code the shadows will hold after the next advance
    wire [2:0] next_code = at_top ? base_code : voted + 3'd1;
  // Diverse terminal check for the precedence path: it re-derives the wrap
  // condition from the step index and the configured ramp length instead of
  // reusing the voter's flag or its code compare.
  wire       prev_wrap = (pos == ring_len);
