module debounce_hist_arm (
    input  wire i_clk,
    input  wire i_ce,
    input  wire i_raw,
    output wire o_clean,
    output wire o_armed,
    output wire o_settled
);
    // K identical consecutive samples are required before the clean output flips.
    localparam [2:0] KC = 3'd4;
   localparam [2:0] KS = 3'd6;   // validated filter: longer confirm window
    localparam       HW = 8;

    reg [2:0]      cnt;     // stability counter, saturates at KC
    reg            sample;  // current candidate level being timed
    reg            clean;   // debounced (committed) level
    reg [HW-1:0]   hist;    // raw sample history, hist[0] is the newest sample
    reg            armed;   // sticky: set the first time the filter commits
   reg            stable;  // registered settled flag, drives o_settled
reg            pend;    // pending level change: candidate differs from the committed level
   reg            tgt;     // latched target level of the outstanding change request
   reg [3:0]      n_req;   // ledger: change requests logged (free-running, wraps)
   reg [3:0]      n_ret;   // ledger: change requests retired (free-running, wraps)
  reg            clean_s; // validated level published by the slow filter
  reg            pend_s;  // validated change pending against clean_s
  reg            armed_s; // sticky: the slow filter has committed once

    initial cnt    = 3'd0;
    initial sample = 1'b0;
    initial clean  = 1'b0;
    initial hist   = {HW{1'b0}};
    initial armed  = 1'b0;
   initial stable = 1'b0;
initial pend   = 1'b0;
   initial tgt    = 1'b0;
   initial n_req  = 4'd0;
   initial n_ret  = 4'd0;
  initial clean_s = 1'b0;
  initial pend_s  = 1'b0;
  initial armed_s = 1'b0;

  // Level the validated filter will publish at its next commit.
  wire s_lvl = clean_s ^ pend_s;

    always @(posedge i_clk) if (i_ce) begin
        hist <= { hist[HW-2:0], i_raw };
        if (i_raw != sample) begin
            // new level seen: retime from scratch
            sample <= i_raw;
            cnt    <= 3'd0;
           stable <= 1'b0;
pend   <= i_raw ^ clean;
          pend_s <= i_raw ^ clean_s;
           // A retime either opens a new request against the committed level or
           // retires the one already logged; the target level is captured on open.
           if (n_req == n_ret) begin
               tgt   <= i_raw;
               n_req <= n_req + 4'd1;
           end else begin
               n_ret <= n_ret + 4'd1;
           end
       end else if (cnt < KS) begin
            cnt <= cnt + 3'd1;
            if (cnt == (KC - 3'd1)) begin
                // KC identical consecutive samples: commit the level
               if (pend) begin
                   clean <= tgt;
                   n_ret <= n_ret + 4'd1;
               end
pend  <= 1'b0;
                armed <= 1'b1;
               stable <= 1'b1;
            end
           if (cnt == (KS - 3'd1)) begin
               // KS identical samples: the validated filter commits.  It is the
               // authority on the level, so a fast output that has drifted away
               // is resynced here and its outstanding request retired.
               clean_s <= s_lvl;
               pend_s  <= 1'b0;
               armed_s <= 1'b1;
               if (s_lvl != clean) begin
                   clean <= s_lvl;
                   if (pend) n_ret <= n_ret + 4'd1;
                   pend  <= 1'b0;
               end
           end
        end
    end

    assign o_clean   = clean;
   assign o_armed   = armed && armed_s;
   assign o_settled = stable;

    // Universality, after the filter has armed: whenever the stability counter
    // is nonzero the two newest raw samples must agree.
    always @(*)
        if (armed)
            assert ((cnt == 3'd0) || (hist[1] == hist[0]));

   // While the filter reports settled, the committed level must still match the
   // newest raw sample: any disagreement would mean a missed retime.
   always @(posedge i_clk)
       assert (!stable || (clean == hist[0]));
endmodule

